  1→import { createHash, randomBytes, timingSafeEqual } from "node:crypto";
  2→import { and, eq, isNull, sql } from "drizzle-orm";
  3→import type { Db } from "@paperclipai/db";
  4→import {
  5→  authUsers,
  6→  boardApiKeys,
  7→  cliAuthChallenges,
  8→  companies,
  9→  companyMemberships,
 10→  instanceUserRoles,
 11→} from "@paperclipai/db";
 12→import { conflict, forbidden, notFound } from "../errors.js";
 13→
 14→export const BOARD_API_KEY_TTL_MS = 30 * 24 * 60 * 60 * 1000;
 15→export const CLI_AUTH_CHALLENGE_TTL_MS = 10 * 60 * 1000;
 16→
 17→export type CliAuthChallengeStatus = "pending" | "approved" | "cancelled" | "expired";
 18→
 19→export function hashBearerToken(token: string) {
 20→  return createHash("sha256").update(token).digest("hex");
 21→}
 22→
 23→export function tokenHashesMatch(left: string, right: string) {
 24→  const leftBytes = Buffer.from(left, "utf8");
 25→  const rightBytes = Buffer.from(right, "utf8");
 26→  return leftBytes.length === rightBytes.length && timingSafeEqual(leftBytes, rightBytes);
 27→}
 28→
 29→export function createBoardApiToken() {
 30→  return `pcp_board_${randomBytes(24).toString("hex")}`;
 31→}
 32→
 33→export function createCliAuthSecret() {
 34→  return `pcp_cli_auth_${randomBytes(24).toString("hex")}`;
 35→}
 36→
 37→export function boardApiKeyExpiresAt(nowMs: number = Date.now()) {
 38→  return new Date(nowMs + BOARD_API_KEY_TTL_MS);
 39→}
 40→
 41→export function cliAuthChallengeExpiresAt(nowMs: number = Date.now()) {
 42→  return new Date(nowMs + CLI_AUTH_CHALLENGE_TTL_MS);
 43→}
 44→
 45→function challengeStatusForRow(row: typeof cliAuthChallenges.$inferSelect): CliAuthChallengeStatus {
 46→  if (row.cancelledAt) return "cancelled";
 47→  if (row.expiresAt.getTime() <= Date.now()) return "expired";
 48→  if (row.approvedAt && row.boardApiKeyId) return "approved";
 49→  return "pending";
 50→}
 51→
 52→export function boardAuthService(db: Db) {
 53→  async function resolveBoardAccess(userId: string) {
 54→    const [user, memberships, adminRole] = await Promise.all([
 55→      db
 56→        .select({
 57→          id: authUsers.id,
 58→          name: authUsers.name,
 59→          email: authUsers.email,
 60→        })
 61→        .from(authUsers)
 62→        .where(eq(authUsers.id, userId))
 63→        .then((rows) => rows[0] ?? null),
 64→      db
 65→        .select({ companyId: companyMemberships.companyId })
 66→        .from(companyMemberships)
 67→        .where(
 68→          and(
 69→            eq(companyMemberships.principalType, "user"),
 70→            eq(companyMemberships.principalId, userId),
 71→            eq(companyMemberships.status, "active"),
 72→          ),
 73→        )
 74→        .then((rows) => rows.map((row) => row.companyId)),
 75→      db
 76→        .select({ id: instanceUserRoles.id })
 77→        .from(instanceUserRoles)
 78→        .where(and(eq(instanceUserRoles.userId, userId), eq(instanceUserRoles.role, "instance_admin")))
 79→        .then((rows) => rows[0] ?? null),
 80→    ]);
 81→
 82→    return {
 83→      user,
 84→      companyIds: memberships,
 85→      isInstanceAdmin: Boolean(adminRole),
 86→    };
 87→  }
 88→
 89→  async function resolveBoardActivityCompanyIds(input: {
 90→    userId: string;
 91→    requestedCompanyId?: string | null;
 92→    boardApiKeyId?: string | null;
 93→  }) {
 94→    const access = await resolveBoardAccess(input.userId);
 95→    const companyIds = new Set(access.companyIds);
 96→
 97→    if (companyIds.size === 0 && input.requestedCompanyId?.trim()) {
 98→      companyIds.add(input.requestedCompanyId.trim());
 99→    }
100→
101→    if (companyIds.size === 0 && input.boardApiKeyId?.trim()) {
102→      const challengeCompanyIds = await db
103→        .select({ requestedCompanyId: cliAuthChallenges.requestedCompanyId })
104→        .from(cliAuthChallenges)
105→        .where(eq(cliAuthChallenges.boardApiKeyId, input.boardApiKeyId.trim()))
106→        .then((rows) =>
107→          rows
108→            .map((row) => row.requestedCompanyId?.trim() ?? null)
109→            .filter((value): value is string => Boolean(value)),
110→        );
111→      for (const companyId of challengeCompanyIds) {
112→        companyIds.add(companyId);
113→      }
114→    }
115→
116→    if (companyIds.size === 0 && access.isInstanceAdmin) {
117→      const allCompanyIds = await db
118→        .select({ id: companies.id })
119→        .from(companies)
120→        .then((rows) => rows.map((row) => row.id));
121→      for (const companyId of allCompanyIds) {
122→        companyIds.add(companyId);
123→      }
124→    }
125→
126→    return Array.from(companyIds);
127→  }
128→
129→  async function findBoardApiKeyByToken(token: string) {
130→    const tokenHash = hashBearerToken(token);
131→    const now = new Date();
132→    return db
133→      .select()
134→      .from(boardApiKeys)
135→      .where(
136→        and(
137→          eq(boardApiKeys.keyHash, tokenHash),
138→          isNull(boardApiKeys.revokedAt),
139→        ),
140→      )
141→      .then((rows) => rows.find((row) => !row.expiresAt || row.expiresAt.getTime() > now.getTime()) ?? null);
142→  }
143→
144→  async function touchBoardApiKey(id: string) {
145→    await db.update(boardApiKeys).set({ lastUsedAt: new Date() }).where(eq(boardApiKeys.id, id));
146→  }
147→
148→  async function revokeBoardApiKey(id: string) {
149→    const now = new Date();
150→    return db
151→      .update(boardApiKeys)
152→      .set({ revokedAt: now, lastUsedAt: now })
153→      .where(and(eq(boardApiKeys.id, id), isNull(boardApiKeys.revokedAt)))
154→      .returning()
155→      .then((rows) => rows[0] ?? null);
156→  }
157→
158→  async function createCliAuthChallenge(input: {
159→    command: string;
160→    clientName?: string | null;
161→    requestedAccess: "board" | "instance_admin_required";
162→    requestedCompanyId?: string | null;
163→  }) {
164→    const challengeSecret = createCliAuthSecret();
165→    const pendingBoardToken = createBoardApiToken();
166→    const expiresAt = cliAuthChallengeExpiresAt();
167→    const labelBase = input.clientName?.trim() || "paperclipai cli";
168→    const pendingKeyName =
169→      input.requestedAccess === "instance_admin_required"
170→        ? `${labelBase} (instance admin)`
171→        : `${labelBase} (board)`;
172→
173→    const created = await db
174→      .insert(cliAuthChallenges)
175→      .values({
176→        secretHash: hashBearerToken(challengeSecret),
177→        command: input.command.trim(),
178→        clientName: input.clientName?.trim() || null,
179→        requestedAccess: input.requestedAccess,
180→        requestedCompanyId: input.requestedCompanyId?.trim() || null,
181→        pendingKeyHash: hashBearerToken(pendingBoardToken),
182→        pendingKeyName,
183→        expiresAt,
184→      })
185→      .returning()
186→      .then((rows) => rows[0]);
187→
188→    return {
189→      challenge: created,
190→      challengeSecret,
191→      pendingBoardToken,
192→    };
193→  }
194→
195→  async function getCliAuthChallenge(id: string) {
196→    return db
197→      .select()
198→      .from(cliAuthChallenges)
199→      .where(eq(cliAuthChallenges.id, id))
200→      .then((rows) => rows[0] ?? null);
201→  }
202→
203→  async function getCliAuthChallengeBySecret(id: string, token: string) {
204→    const challenge = await getCliAuthChallenge(id);
205→    if (!challenge) return null;
206→    if (!tokenHashesMatch(challenge.secretHash, hashBearerToken(token))) return null;
207→    return challenge;
208→  }
209→
210→  async function describeCliAuthChallenge(id: string, token: string) {
211→    const challenge = await getCliAuthChallengeBySecret(id, token);
212→    if (!challenge) return null;
213→
214→    const [company, approvedBy] = await Promise.all([
215→      challenge.requestedCompanyId
216→        ? db
217→            .select({ id: companies.id, name: companies.name })
218→            .from(companies)
219→            .where(eq(companies.id, challenge.requestedCompanyId))
220→            .then((rows) => rows[0] ?? null)
221→        : Promise.resolve(null),
222→      challenge.approvedByUserId
223→        ? db
224→            .select({ id: authUsers.id, name: authUsers.name, email: authUsers.email })
225→            .from(authUsers)
226→            .where(eq(authUsers.id, challenge.approvedByUserId))
227→            .then((rows) => rows[0] ?? null)
228→        : Promise.resolve(null),
229→    ]);
230→
231→    return {
232→      id: challenge.id,
233→      status: challengeStatusForRow(challenge),
234→      command: challenge.command,
235→      clientName: challenge.clientName ?? null,
236→      requestedAccess: challenge.requestedAccess as "board" | "instance_admin_required",
237→      requestedCompanyId: challenge.requestedCompanyId ?? null,
238→      requestedCompanyName: company?.name ?? null,
239→      approvedAt: challenge.approvedAt?.toISOString() ?? null,
240→      cancelledAt: challenge.cancelledAt?.toISOString() ?? null,
241→      expiresAt: challenge.expiresAt.toISOString(),
242→      approvedByUser: approvedBy
243→        ? {
244→            id: approvedBy.id,
245→            name: approvedBy.name,
246→            email: approvedBy.email,
247→          }
248→        : null,
249→    };
250→  }
251→
252→  async function approveCliAuthChallenge(id: string, token: string, userId: string) {
253→    const access = await resolveBoardAccess(userId);
254→    return db.transaction(async (tx) => {
255→      await tx.execute(
256→        sql`select ${cliAuthChallenges.id} from ${cliAuthChallenges} where ${cliAuthChallenges.id} = ${id} for update`,
257→      );
258→
259→      const challenge = await tx
260→        .select()
261→        .from(cliAuthChallenges)
262→        .where(eq(cliAuthChallenges.id, id))
263→        .then((rows) => rows[0] ?? null);
264→      if (!challenge || !tokenHashesMatch(challenge.secretHash, hashBearerToken(token))) {
265→        throw notFound("CLI auth challenge not found");
266→      }
267→
268→      const status = challengeStatusForRow(challenge);
269→      if (status === "expired") return { status, challenge };
270→      if (status === "cancelled") return { status, challenge };
271→
272→      if (challenge.requestedAccess === "instance_admin_required" && !access.isInstanceAdmin) {
273→        throw forbidden("Instance admin required");
274→      }
275→
276→      let boardKeyId = challenge.boardApiKeyId;
277→      if (!boardKeyId) {
278→        const createdKey = await tx
279→          .insert(boardApiKeys)
280→          .values({
281→            userId,
282→            name: challenge.pendingKeyName,
283→            keyHash: challenge.pendingKeyHash,
284→            expiresAt: boardApiKeyExpiresAt(),
285→          })
286→          .returning()
287→          .then((rows) => rows[0]);
288→        boardKeyId = createdKey.id;
289→      }
290→
291→      const approvedAt = challenge.approvedAt ?? new Date();
292→      const updated = await tx
293→        .update(cliAuthChallenges)
294→        .set({
295→          approvedByUserId: userId,
296→          boardApiKeyId: boardKeyId,
297→          approvedAt,
298→          updatedAt: new Date(),
299→        })
300→        .where(eq(cliAuthChallenges.id, challenge.id))
301→        .returning()
302→        .then((rows) => rows[0] ?? challenge);
303→
304→      return { status: "approved" as const, challenge: updated };
305→    });
306→  }
307→
308→  async function cancelCliAuthChallenge(id: string, token: string) {
309→    const challenge = await getCliAuthChallengeBySecret(id, token);
310→    if (!challenge) throw notFound("CLI auth challenge not found");
311→
312→    const status = challengeStatusForRow(challenge);
313→    if (status === "approved") return { status, challenge };
314→    if (status === "expired") return { status, challenge };
315→    if (status === "cancelled") return { status, challenge };
316→
317→    const updated = await db
318→      .update(cliAuthChallenges)
319→      .set({
320→        cancelledAt: new Date(),
321→        updatedAt: new Date(),
322→      })
323→      .where(eq(cliAuthChallenges.id, challenge.id))
324→      .returning()
325→      .then((rows) => rows[0] ?? challenge);
326→
327→    return { status: "cancelled" as const, challenge: updated };
328→  }
329→
330→  async function assertCurrentBoardKey(keyId: string | undefined, userId: string | undefined) {
331→    if (!keyId || !userId) throw conflict("Board API key context is required");
332→    const key = await db
333→      .select()
334→      .from(boardApiKeys)
335→      .where(and(eq(boardApiKeys.id, keyId), eq(boardApiKeys.userId, userId)))
336→      .then((rows) => rows[0] ?? null);
337→    if (!key || key.revokedAt) throw notFound("Board API key not found");
338→    return key;
339→  }
340→
341→  return {
342→    resolveBoardAccess,
343→    findBoardApiKeyByToken,
344→    touchBoardApiKey,
345→    revokeBoardApiKey,
346→    createCliAuthChallenge,
347→    getCliAuthChallengeBySecret,
348→    describeCliAuthChallenge,
349→    approveCliAuthChallenge,
350→    cancelCliAuthChallenge,
351→    assertCurrentBoardKey,
352→    resolveBoardActivityCompanyIds,
353→  };
354→}
