  1→import type { Request, RequestHandler } from "express";
  2→import type { IncomingHttpHeaders } from "node:http";
  3→import { betterAuth } from "better-auth";
  4→import { drizzleAdapter } from "better-auth/adapters/drizzle";
  5→import { toNodeHandler } from "better-auth/node";
  6→import type { Db } from "@paperclipai/db";
  7→import {
  8→  authAccounts,
  9→  authSessions,
 10→  authUsers,
 11→  authVerifications,
 12→} from "@paperclipai/db";
 13→import type { Config } from "../config.js";
 14→
 15→export type BetterAuthSessionUser = {
 16→  id: string;
 17→  email?: string | null;
 18→  name?: string | null;
 19→};
 20→
 21→export type BetterAuthSessionResult = {
 22→  session: { id: string; userId: string } | null;
 23→  user: BetterAuthSessionUser | null;
 24→};
 25→
 26→type BetterAuthInstance = ReturnType<typeof betterAuth>;
 27→
 28→function headersFromNodeHeaders(rawHeaders: IncomingHttpHeaders): Headers {
 29→  const headers = new Headers();
 30→  for (const [key, raw] of Object.entries(rawHeaders)) {
 31→    if (!raw) continue;
 32→    if (Array.isArray(raw)) {
 33→      for (const value of raw) headers.append(key, value);
 34→      continue;
 35→    }
 36→    headers.set(key, raw);
 37→  }
 38→  return headers;
 39→}
 40→
 41→function headersFromExpressRequest(req: Request): Headers {
 42→  return headersFromNodeHeaders(req.headers);
 43→}
 44→
 45→export function deriveAuthTrustedOrigins(config: Config): string[] {
 46→  const baseUrl = config.authBaseUrlMode === "explicit" ? config.authPublicBaseUrl : undefined;
 47→  const trustedOrigins = new Set<string>();
 48→
 49→  if (baseUrl) {
 50→    try {
 51→      trustedOrigins.add(new URL(baseUrl).origin);
 52→    } catch {
 53→      // Better Auth will surface invalid base URL separately.
 54→    }
 55→  }
 56→  if (config.deploymentMode === "authenticated") {
 57→    for (const hostname of config.allowedHostnames) {
 58→      const trimmed = hostname.trim().toLowerCase();
 59→      if (!trimmed) continue;
 60→      trustedOrigins.add(`https://${trimmed}`);
 61→      trustedOrigins.add(`http://${trimmed}`);
 62→    }
 63→  }
 64→
 65→  return Array.from(trustedOrigins);
 66→}
 67→
 68→export function createBetterAuthInstance(db: Db, config: Config, trustedOrigins?: string[]): BetterAuthInstance {
 69→  const baseUrl = config.authBaseUrlMode === "explicit" ? config.authPublicBaseUrl : undefined;
 70→  const secret = process.env.BETTER_AUTH_SECRET ?? process.env.PAPERCLIP_AGENT_JWT_SECRET ?? "paperclip-dev-secret";
 71→  const effectiveTrustedOrigins = trustedOrigins ?? deriveAuthTrustedOrigins(config);
 72→
 73→  const publicUrl = process.env.PAPERCLIP_PUBLIC_URL ?? baseUrl;
 74→  const isHttpOnly = publicUrl ? publicUrl.startsWith("http://") : false;
 75→
 76→  const authConfig = {
 77→    baseURL: baseUrl,
 78→    secret,
 79→    trustedOrigins: effectiveTrustedOrigins,
 80→    database: drizzleAdapter(db, {
 81→      provider: "pg",
 82→      schema: {
 83→        user: authUsers,
 84→        session: authSessions,
 85→        account: authAccounts,
 86→        verification: authVerifications,
 87→      },
 88→    }),
 89→    emailAndPassword: {
 90→      enabled: true,
 91→      requireEmailVerification: false,
 92→      disableSignUp: config.authDisableSignUp,
 93→    },
 94→    ...(isHttpOnly ? { advanced: { useSecureCookies: false } } : {}),
 95→  };
 96→
 97→  if (!baseUrl) {
 98→    delete (authConfig as { baseURL?: string }).baseURL;
 99→  }
100→
101→  return betterAuth(authConfig);
102→}
103→
104→export function createBetterAuthHandler(auth: BetterAuthInstance): RequestHandler {
105→  const handler = toNodeHandler(auth);
106→  return (req, res, next) => {
107→    void Promise.resolve(handler(req, res)).catch(next);
108→  };
109→}
110→
111→export async function resolveBetterAuthSessionFromHeaders(
112→  auth: BetterAuthInstance,
113→  headers: Headers,
114→): Promise<BetterAuthSessionResult | null> {
115→  const api = (auth as unknown as { api?: { getSession?: (input: unknown) => Promise<unknown> } }).api;
116→  if (!api?.getSession) return null;
117→
118→  const sessionValue = await api.getSession({
119→    headers,
120→  });
121→  if (!sessionValue || typeof sessionValue !== "object") return null;
122→
123→  const value = sessionValue as {
124→    session?: { id?: string; userId?: string } | null;
125→    user?: { id?: string; email?: string | null; name?: string | null } | null;
126→  };
127→  const session = value.session?.id && value.session.userId
128→    ? { id: value.session.id, userId: value.session.userId }
129→    : null;
130→  const user = value.user?.id
131→    ? {
132→        id: value.user.id,
133→        email: value.user.email ?? null,
134→        name: value.user.name ?? null,
