12→  if (!userValue || typeof userValue !== "object") return null;
13→  const session = sessionValue as Record<string, unknown>;
14→  const user = userValue as Record<string, unknown>;
15→  if (typeof session.id !== "string" || typeof session.userId !== "string") return null;
16→  if (typeof user.id !== "string") return null;
17→  return {
18→    session: { id: session.id, userId: session.userId },
19→    user: {
