10→export function assertInstanceAdmin(req: Request) {
11→  assertBoard(req);
12→  if (req.actor.source === "local_implicit" || req.actor.isInstanceAdmin) {
13→    return;
14→  }
15→  throw forbidden("Instance admin access required");
16→}
