  1→import { createHash } from "node:crypto";
  2→import type { Request, RequestHandler } from "express";
  3→import { and, eq, isNull } from "drizzle-orm";
  4→import type { Db } from "@paperclipai/db";
  5→import { agentApiKeys, agents, companyMemberships, instanceUserRoles } from "@paperclipai/db";
  6→import { verifyLocalAgentJwt } from "../agent-auth-jwt.js";
  7→import type { DeploymentMode } from "@paperclipai/shared";
  8→import type { BetterAuthSessionResult } from "../auth/better-auth.js";
  9→import { logger } from "./logger.js";
 10→import { boardAuthService } from "../services/board-auth.js";
 11→
 12→function hashToken(token: string) {
 13→  return createHash("sha256").update(token).digest("hex");
 14→}
 15→
 16→interface ActorMiddlewareOptions {
 17→  deploymentMode: DeploymentMode;
 18→  resolveSession?: (req: Request) => Promise<BetterAuthSessionResult | null>;
 19→}
 20→
 21→export function actorMiddleware(db: Db, opts: ActorMiddlewareOptions): RequestHandler {
 22→  const boardAuth = boardAuthService(db);
 23→  return async (req, _res, next) => {
 24→    req.actor =
 25→      opts.deploymentMode === "local_trusted"
 26→        ? { type: "board", userId: "local-board", isInstanceAdmin: true, source: "local_implicit" }
 27→        : { type: "none", source: "none" };
 28→
 29→    const runIdHeader = req.header("x-paperclip-run-id");
 30→
 31→    const authHeader = req.header("authorization");
 32→    if (!authHeader?.toLowerCase().startsWith("bearer ")) {
 33→      if (opts.deploymentMode === "authenticated" && opts.resolveSession) {
 34→        let session: BetterAuthSessionResult | null = null;
 35→        try {
 36→          session = await opts.resolveSession(req);
 37→        } catch (err) {
 38→          logger.warn(
 39→            { err, method: req.method, url: req.originalUrl },
 40→            "Failed to resolve auth session from request headers",
 41→          );
 42→        }
 43→        if (session?.user?.id) {
 44→          const userId = session.user.id;
 45→          const [roleRow, memberships] = await Promise.all([
 46→            db
 47→              .select({ id: instanceUserRoles.id })
 48→              .from(instanceUserRoles)
 49→              .where(and(eq(instanceUserRoles.userId, userId), eq(instanceUserRoles.role, "instance_admin")))
 50→              .then((rows) => rows[0] ?? null),
 51→            db
 52→              .select({ companyId: companyMemberships.companyId })
 53→              .from(companyMemberships)
 54→              .where(
 55→                and(
 56→                  eq(companyMemberships.principalType, "user"),
 57→                  eq(companyMemberships.principalId, userId),
 58→                  eq(companyMemberships.status, "active"),
 59→                ),
 60→              ),
 61→          ]);
 62→          req.actor = {
 63→            type: "board",
 64→            userId,
 65→            companyIds: memberships.map((row) => row.companyId),
 66→            isInstanceAdmin: Boolean(roleRow),
 67→            runId: runIdHeader ?? undefined,
 68→            source: "session",
 69→          };
 70→          next();
 71→          return;
 72→        }
 73→      }
 74→      if (runIdHeader) req.actor.runId = runIdHeader;
 75→      next();
 76→      return;
 77→    }
 78→
 79→    const token = authHeader.slice("bearer ".length).trim();
 80→    if (!token) {
 81→      next();
 82→      return;
 83→    }
 84→
 85→    const boardKey = await boardAuth.findBoardApiKeyByToken(token);
 86→    if (boardKey) {
 87→      const access = await boardAuth.resolveBoardAccess(boardKey.userId);
 88→      if (access.user) {
 89→        await boardAuth.touchBoardApiKey(boardKey.id);
 90→        req.actor = {
 91→          type: "board",
 92→          userId: boardKey.userId,
 93→          companyIds: access.companyIds,
 94→          isInstanceAdmin: access.isInstanceAdmin,
 95→          keyId: boardKey.id,
 96→          runId: runIdHeader || undefined,
 97→          source: "board_key",
 98→        };
 99→        next();
100→        return;
101→      }
102→    }
103→
104→    const tokenHash = hashToken(token);
105→    const key = await db
106→      .select()
107→      .from(agentApiKeys)
108→      .where(and(eq(agentApiKeys.keyHash, tokenHash), isNull(agentApiKeys.revokedAt)))
109→      .then((rows) => rows[0] ?? null);
110→
111→    if (!key) {
112→      const claims = verifyLocalAgentJwt(token);
113→      if (!claims) {
114→        next();
115→        return;
116→      }
117→
118→      const agentRecord = await db
119→        .select()
120→        .from(agents)
121→        .where(eq(agents.id, claims.sub))
122→        .then((rows) => rows[0] ?? null);
123→
124→      if (!agentRecord || agentRecord.companyId !== claims.company_id) {
125→        next();
126→        return;
127→      }
128→
129→      if (agentRecord.status === "terminated" || agentRecord.status === "pending_approval") {
130→        next();
131→        return;
132→      }
133→
134→      req.actor = {
135→        type: "agent",
136→        agentId: claims.sub,
137→        companyId: claims.company_id,
138→        keyId: undefined,
139→        runId: runIdHeader || claims.run_id || undefined,
140→        source: "agent_jwt",
141→      };
142→      next();
143→      return;
144→    }
145→
146→    await db
147→      .update(agentApiKeys)
148→      .set({ lastUsedAt: new Date() })
149→      .where(eq(agentApiKeys.id, key.id));
150→
151→    const agentRecord = await db
152→      .select()
153→      .from(agents)
154→      .where(eq(agents.id, key.agentId))
155→      .then((rows) => rows[0] ?? null);
156→
157→    if (!agentRecord || agentRecord.status === "terminated" || agentRecord.status === "pending_approval") {
158→      next();
159→      return;
160→    }
161→
162→    req.actor = {
163→      type: "agent",
164→      agentId: key.agentId,
165→      companyId: key.companyId,
166→      keyId: key.id,
167→      runId: runIdHeader || undefined,
168→      source: "agent_key",
169→    };
170→
171→    next();
172→  };
173→}
174→
175→export function requireBoard(req: Express.Request) {
176→  return req.actor.type === "board";
177→}
