180→    await db.transaction(async (tx) => {
181→      const toDelete = existing.filter((row) => !target.has(row.companyId)).map((row) => row.id);
182→      if (toDelete.length > 0) {
183→        await tx.delete(companyMemberships).where(inArray(companyMemberships.id, toDelete));
184→      }
185→
186→      for (const companyId of target) {
187→        if (existingByCompany.has(companyId)) continue;
188→        await tx.insert(companyMemberships).values({
189→          companyId,
190→          principalType: "user",
191→          principalId: userId,
192→          status: "active",
193→          membershipRole: "member",
