## COMPLETE RBAC SYSTEM ANALYSIS

### 1. AUTH.TS - User Authentication Schema
**File:** `/Users/vuongluu/Documents/jobs/lab3/paperclip/paperclip/packages/db/src/schema/auth.ts`

```typescript
// User authentication via better-auth
authUsers: {
  id: text (PK)
  name: text (NOT NULL)
  email: text (NOT NULL)
  emailVerified: boolean (default: false)
  image: text
  createdAt: timestamp with timezone
  updatedAt: timestamp with timezone
}

// Session management
authSessions: {
  id: text (PK)
  expiresAt: timestamp
  token: text
  createdAt, updatedAt: timestamps
  ipAddress, userAgent: text
  userId: text (FK → authUsers.id, cascade delete)
}

// OAuth/multi-provider support
authAccounts: {
  id: text (PK)
  accountId, providerId: text
  userId: text (FK → authUsers.id, cascade delete)
  accessToken, refreshToken, idToken: text
  accessTokenExpiresAt, refreshTokenExpiresAt: timestamps
  scope, password: text
  createdAt, updatedAt: timestamps
}

// Email verification flow
authVerifications: {
  id: text (PK)
  identifier, value: text
  expiresAt: timestamp
  createdAt, updatedAt: timestamps
}
```

### 2. INSTANCE_USER_ROLES.TS - Instance-Level Admin Roles
**File:** `/Users/vuongluu/Documents/jobs/lab3/paperclip/paperclip/packages/db/src/schema/instance_user_roles.ts`

```typescript
instanceUserRoles: {
  id: uuid (PK, default: random)
  userId: text (NOT NULL) - references authUsers.id
  role: text (NOT NULL, default: "instance_admin")
  createdAt: timestamp (default: now, with timezone)
  updatedAt: timestamp (default: now, with timezone)

  Indexes:
  - uniqueIndex(userId, role) - prevents duplicate roles per user
  - index(role)
}

// Only current role value: "instance_admin"
```

### 3. COMPANY_MEMBERSHIPS.TS - Company Access Control
**File:** `/Users/vuongluu/Documents/jobs/lab3/paperclip/paperclip/packages/db/src/schema/company_memberships.ts`

```typescript
companyMemberships: {
  id: uuid (PK, default: random)
  companyId: uuid (NOT NULL, FK → companies.id)
  principalType: text (NOT NULL) - "user" | "agent"
  principalId: text (NOT NULL)
  status: text (default: "active") - "pending" | "active" | "suspended"
  membershipRole: text - optional role qualifier (e.g., "owner", "member")
  createdAt: timestamp (default: now)
  updatedAt: timestamp (default: now)

  Indexes:
  - uniqueIndex(companyId, principalType, principalId)
  - index(principalType, principalId, status)
  - index(companyId, status)
}
```

### 4. CONSTANTS.TS - Permission & Role Definitions
**File:** `/Users/vuongluu/Documents/jobs/lab3/paperclip/paperclip/packages/shared/src/constants.ts` (lines 323-352)

```typescript
// Principal types (who can be a member)
PRINCIPAL_TYPES = ["user", "agent"]

// Membership status lifecycle
MEMBERSHIP_STATUSES = ["pending", "active", "suspended"]

// Instance-level admin role
INSTANCE_USER_ROLES = ["instance_admin"]

// Company membership roles
// (implicit: "owner", "member", and others defined by membershipRole field)

// Permission keys - the core RBAC permission set
PERMISSION_KEYS = [
  "agents:create",           // Create new agents
  "users:invite",            // Invite users to company
  "users:manage_permissions", // Grant/revoke permissions
  "tasks:assign",            // Assign tasks
  "tasks:assign_scope",      // Assign tasks with scope restrictions
  "joins:approve",           // Approve join requests
]
```

### 5. SERVER AUTH MIDDLEWARE - Actor Resolution
**File:** `/Users/vuongluu/Documents/jobs/lab3/paperclip/paperclip/server/src/middleware/auth.ts`

```typescript
// Actor types populated in req.actor:
Actor = {
  type: "board" | "agent" | "none",
  userId?: string,              // For board actors (users)
  agentId?: string,             // For agent actors
  companyId?: string,           // For agent actors (single company)
  companyIds?: string[],        // For board actors (multiple companies)
  isInstanceAdmin?: boolean,    // If user is instance_admin
  keyId?: string,               // API key ID
  runId?: string,               // Run context
  source: "local_implicit" | "session" | "board_key" | "agent_key" | "agent_jwt" | "none"
}

// Resolution order:
// 1. local_trusted mode → default to local-board with instance admin
// 2. Session cookie (better-auth) → board actor with company memberships
// 3. Bearer token (board API key) → board actor with company access
// 4. Bearer token (agent API key hash) → agent actor
// 5. Bearer token (agent JWT) → agent actor with JWT claims
// 6. No auth → type: "none"
```

### 6. AUTHZ.TS - Authorization Routes & Checks
**File:** `/Users/vuongluu/Documents/jobs/lab3/paperclip/paperclip/server/src/routes/authz.ts`

