          <Button
            onClick={() => updateMutation.mutate({ name })}
            disabled={updateMutation.isPending}
          >
            {updateMutation.isPending ? "Saving..." : "Save changes"}
          </Button>
          <Button variant="ghost" onClick={() => setName(user.name)}>
            Cancel
          </Button>
