                  className="accent-primary"
                />
                <span className="text-sm">{ROLE_LABELS[r]}</span>
              </label>
            ))}
          </div>
          <DialogFooter>
            <Button
              onClick={() => {
                const selected = document.querySelector<HTMLInputElement>(
                  'input[name="role"]:checked'
                );
                if (selected && roleUser) {
                  roleMutation.mutate({ id: roleUser.id, role: selected.value });
                }
              }}
              disabled={roleMutation.isPending}
            >
              {roleMutation.isPending ? "Saving..." : "Save"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}
