314→            eq(principalPermissionGrants.companyId, companyId),
315→            eq(principalPermissionGrants.principalType, principalType),
316→            eq(principalPermissionGrants.principalId, principalId),
317→            eq(principalPermissionGrants.permissionKey, permissionKey),
318→          ),
319→        );
320→      return;
321→    }
322→
323→    await ensureMembership(companyId, principalType, principalId, "member", "active");
324→
325→    const existing = await db
326→      .select()
327→      .from(principalPermissionGrants)
328→      .where(
329→        and(
330→          eq(principalPermissionGrants.companyId, companyId),
331→          eq(principalPermissionGrants.principalType, principalType),
332→          eq(principalPermissionGrants.principalId, principalId),
333→          eq(principalPermissionGrants.permissionKey, permissionKey),
334→        ),
335→      )
336→      .then((rows) => rows[0] ?? null);
337→
338→    if (existing) {
339→      await db
340→        .update(principalPermissionGrants)
341→        .set({
342→          scope,
343→          grantedByUserId,
344→          updatedAt: new Date(),
345→        })
346→        .where(eq(principalPermissionGrants.id, existing.id));
347→      return;
348→    }
349→
350→    await db.insert(principalPermissionGrants).values({
351→      companyId,
352→      principalType,
353→      principalId,
354→      permissionKey,
355→      scope,
356→      grantedByUserId,
357→      createdAt: new Date(),
358→      updatedAt: new Date(),
359→    });
360→  }
361→
362→  return {
