 20→async function materializeInstructions(role: string): Promise<string | null> {
 21→  const projectRoot = resolveProjectRoot();
 22→  if (!projectRoot) return null;
 23→
 24→  let instructionsDir: string;
 25→  try {
 26→    instructionsDir = resolveAgentInstructionsDir(role);
 27→  } catch {
 28→    return null;
 29→  }
 30→
 31→  // Idempotent: skip if already exists
 32→  try {
 33→    await fs.access(instructionsDir);
 34→    return instructionsDir;
 35→  } catch {
 36→    // Directory doesn't exist, create it
 37→  }
 38→
 39→  const bundleRole = role === "ceo" ? "ceo" : "default";
 40→  const bundle = await loadDefaultAgentInstructionsBundle(bundleRole as "ceo" | "default");
 41→
 42→  await fs.mkdir(instructionsDir, { recursive: true });
 43→  for (const [fileName, content] of Object.entries(bundle)) {
 44→    await fs.writeFile(path.join(instructionsDir, fileName), content, "utf8");
 45→  }
 46→
 47→  logger.info(
 48→    { role, instructionsDir, files: Object.keys(bundle) },
 49→    "Materialized default agent instructions to project",
 50→  );
 51→
 52→  return instructionsDir;
 53→}
