 55→export function bootstrapService(db: Db) {
 56→  const isEnabled = process.env.PAPERCLIP_AUTO_BOOTSTRAP !== "false";
 57→
 58→  async function maybeBootstrapUser(
 59→    userId: string,
 60→    userName?: string | null,
 61→  ): Promise<BootstrapResult> {
 62→    if (!isEnabled) return { action: "noop" };
 63→
 64→    // Check if user already has any company memberships
 65→    const existingMemberships = await db
 66→      .select({ id: companyMemberships.id })
 67→      .from(companyMemberships)
 68→      .where(
 69→        and(
 70→          eq(companyMemberships.principalType, "user"),
 71→          eq(companyMemberships.principalId, userId),
 72→          eq(companyMemberships.status, "active"),
 73→        ),
 74→      )
 75→      .limit(1);
 76→
 77→    if (existingMemberships.length > 0) {
 78→      return { action: "noop" };
 79→    }
 80→
 81→    // Check if any companies exist
 82→    const [companyCount] = await db
 83→      .select({ count: count() })
 84→      .from(companies);
 85→
 86→    if (companyCount.count === 0) {
 87→      // First user: create default company + agent, promote to admin
 88→      return createDefaultSetup(userId, userName);
 89→    }
 90→
 91→    // Companies exist but user has no membership: assign to first company
 92→    const [firstCompany] = await db
 93→      .select({ id: companies.id })
 94→      .from(companies)
 95→      .limit(1);
 96→
 97→    if (firstCompany) {
 98→      await db.insert(companyMemberships).values({
 99→        companyId: firstCompany.id,
100→        principalType: "user",
101→        principalId: userId,
102→        status: "active",
103→        membershipRole: "member",
104→      });
105→
106→      logger.info(
107→        { userId, companyId: firstCompany.id },
108→        "Auto-assigned user to existing company",
109→      );
110→
111→      return { action: "assigned_to_company", companyId: firstCompany.id };
112→    }
113→
114→    return { action: "noop" };
115→  }
116→
117→  async function createDefaultSetup(
118→    userId: string,
119→    userName?: string | null,
120→  ): Promise<BootstrapResult> {
121→    const companyName =
122→      process.env.PAPERCLIP_DEFAULT_COMPANY_NAME || "My Company";
123→    const agentName =
124→      process.env.PAPERCLIP_DEFAULT_AGENT_NAME || "CEO Agent";
125→
126→    // Create company
127→    const [company] = await db
128→      .insert(companies)
129→      .values({ name: companyName })
130→      .returning();
131→
132→    // Promote user to instance_admin
133→    const existingRole = await db
134→      .select({ id: instanceUserRoles.id })
135→      .from(instanceUserRoles)
136→      .where(
137→        and(
138→          eq(instanceUserRoles.userId, userId),
139→          eq(instanceUserRoles.role, "instance_admin"),
140→        ),
141→      )
142→      .then((rows) => rows[0] ?? null);
143→
144→    if (!existingRole) {
145→      await db.insert(instanceUserRoles).values({
146→        userId,
147→        role: "instance_admin",
148→      });
149→    }
150→
151→    // Assign user as owner
152→    await db.insert(companyMemberships).values({
153→      companyId: company.id,
154→      principalType: "user",
155→      principalId: userId,
156→      status: "active",
157→      membershipRole: "owner",
158→    });
159→
160→    // Materialize CEO instructions to project-local agents/ceo/
161→    const instructionsDir = await materializeInstructions("ceo");
162→    const projectRoot = resolveProjectRoot();
163→    const ceoCommand = process.env.PAPERCLIP_CEO_COMMAND || "claude";
164→
165→    // Build adapterConfig for claude-local
166→    const adapterConfig: Record<string, unknown> = {};
167→    adapterConfig.command = ceoCommand;
168→    if (projectRoot) {
169→      adapterConfig.cwd = projectRoot;
170→    }
171→    if (instructionsDir) {
172→      adapterConfig.instructionsBundleMode = "external";
173→      adapterConfig.instructionsRootPath = instructionsDir;
174→      adapterConfig.instructionsEntryFile = "AGENTS.md";
175→    }
176→
177→    // Create default CEO agent
178→    await db.insert(agents).values({
179→      companyId: company.id,
180→      name: agentName,
181→      role: "ceo",
182→      title: "Chief Executive Officer",
183→      adapterType: "claude-local",
184→      adapterConfig,
185→    });
186→
187→    logger.info(
188→      { userId, companyId: company.id, companyName, agentName },
189→      "Auto-bootstrap: created default company and agent for first user",
190→    );
191→
192→    return { action: "created_company", companyId: company.id };
193→  }
194→
195→  return { maybeBootstrapUser };
196→}
