 16→type CompanySelectionOptions = { source?: CompanySelectionSource };
 17→
 18→interface CompanyContextValue {
 19→  companies: Company[];
 20→  selectedCompanyId: string | null;
 21→  selectedCompany: Company | null;
 22→  selectionSource: CompanySelectionSource;
 23→  loading: boolean;
 24→  error: Error | null;
 25→  setSelectedCompanyId: (companyId: string, options?: CompanySelectionOptions) => void;
 26→  reloadCompanies: () => Promise<void>;
 27→  createCompany: (data: {
 28→    name: string;
 29→    description?: string | null;
 30→    budgetMonthlyCents?: number;
 31→  }) => Promise<Company>;
 32→}
 33→
 34→const STORAGE_KEY = "paperclip.selectedCompanyId";
 35→
 36→const CompanyContext = createContext<CompanyContextValue | null>(null);
 37→
 38→export function CompanyProvider({ children }: { children: ReactNode }) {
 39→  const queryClient = useQueryClient();
 40→  const [selectionSource, setSelectionSource] = useState<CompanySelectionSource>("bootstrap");
 41→  const [selectedCompanyId, setSelectedCompanyIdState] = useState<string | null>(() => localStorage.getItem(STORAGE_KEY));
 42→
 43→  const { data: companies = [], isLoading, error } = useQuery({
 44→    queryKey: queryKeys.companies.all,
 45→    queryFn: async () => {
 46→      try {
 47→        return await companiesApi.list();
 48→      } catch (err) {
 49→        if (err instanceof ApiError && err.status === 401) {
 50→          return [];
 51→        }
 52→        throw err;
 53→      }
 54→    },
 55→    retry: false,
 56→  });
 57→  const sidebarCompanies = useMemo(
 58→    () => companies.filter((company) => company.status !== "archived"),
 59→    [companies],
 60→  );
 61→
 62→  // Auto-select first company when list loads
 63→  useEffect(() => {
 64→    if (companies.length === 0) return;
 65→
 66→    const selectableCompanies = sidebarCompanies.length > 0 ? sidebarCompanies : companies;
 67→    const stored = localStorage.getItem(STORAGE_KEY);
 68→    if (stored && selectableCompanies.some((c) => c.id === stored)) return;
 69→    if (selectedCompanyId && selectableCompanies.some((c) => c.id === selectedCompanyId)) return;
 70→
 71→    const next = selectableCompanies[0]!.id;
 72→    setSelectedCompanyIdState(next);
 73→    setSelectionSource("bootstrap");
 74→    localStorage.setItem(STORAGE_KEY, next);
 75→  }, [companies, selectedCompanyId, sidebarCompanies]);
 76→
 77→  const setSelectedCompanyId = useCallback((companyId: string, options?: CompanySelectionOptions) => {
 78→    setSelectedCompanyIdState(companyId);
 79→    setSelectionSource(options?.source ?? "manual");
 80→    localStorage.setItem(STORAGE_KEY, companyId);
 81→  }, []);
 82→
 83→  const reloadCompanies = useCallback(async () => {
 84→    await queryClient.invalidateQueries({ queryKey: queryKeys.companies.all });
 85→  }, [queryClient]);
 86→
 87→  const createMutation = useMutation({
 88→    mutationFn: (data: {
 89→      name: string;
 90→      description?: string | null;
 91→      budgetMonthlyCents?: number;
 92→    }) =>
 93→      companiesApi.create(data),
 94→    onSuccess: (company) => {
 95→      queryClient.invalidateQueries({ queryKey: queryKeys.companies.all });
 96→      setSelectedCompanyId(company.id);
 97→    },
 98→  });
 99→
100→  const createCompany = useCallback(
101→    async (data: {
102→      name: string;
103→      description?: string | null;
104→      budgetMonthlyCents?: number;
105→    }) => {
106→      return createMutation.mutateAsync(data);
107→    },
108→    [createMutation],
109→  );
110→
111→  const selectedCompany = useMemo(
112→    () => companies.find((company) => company.id === selectedCompanyId) ?? null,
113→    [companies, selectedCompanyId],
114→  );
115→
116→  const value = useMemo(
117→    () => ({
118→      companies,
119→      selectedCompanyId,
120→      selectedCompany,
121→      selectionSource,
122→      loading: isLoading,
123→      error: error as Error | null,
124→      setSelectedCompanyId,
125→      reloadCompanies,
126→      createCompany,
127→    }),
128→    [
129→      companies,
130→      selectedCompanyId,
131→      selectedCompany,
132→      selectionSource,
133→      isLoading,
134→      error,
135→      setSelectedCompanyId,
136→      reloadCompanies,
137→      createCompany,
138→    ],
139→  );
140→
141→  return <CompanyContext.Provider value={value}>{children}</CompanyContext.Provider>;
142→}
143→
144→export function useCompany() {
145→  const ctx = useContext(CompanyContext);
146→  if (!ctx) {
147→    throw new Error("useCompany must be used within CompanyProvider");
148→  }
149→  return ctx;
150→}
