 69→function CloudAccessGate() {
 70→  const location = useLocation();
 71→  const healthQuery = useQuery({
 72→    queryKey: queryKeys.health,
 73→    queryFn: () => healthApi.get(),
 74→    retry: false,
 75→    refetchInterval: (query) => {
 76→      const data = query.state.data as
 77→        | { deploymentMode?: "local_trusted" | "authenticated"; bootstrapStatus?: "ready" | "bootstrap_pending" }
 78→        | undefined;
 79→      return data?.deploymentMode === "authenticated" && data.bootstrapStatus === "bootstrap_pending"
 80→        ? 2000
 81→        : false;
 82→    },
 83→    refetchIntervalInBackground: true,
 84→  });
 85→
 86→  const isAuthenticatedMode = healthQuery.data?.deploymentMode === "authenticated";
 87→  const sessionQuery = useQuery({
 88→    queryKey: queryKeys.auth.session,
 89→    queryFn: () => authApi.getSession(),
 90→    enabled: isAuthenticatedMode,
 91→    retry: false,
 92→  });
 93→
 94→  if (healthQuery.isLoading || (isAuthenticatedMode && sessionQuery.isLoading)) {
 95→    return <div className="mx-auto max-w-xl py-10 text-sm text-muted-foreground">Loading...</div>;
 96→  }
 97→
 98→  if (healthQuery.error) {
 99→    return (
100→      <div className="mx-auto max-w-xl py-10 text-sm text-destructive">
101→        {healthQuery.error instanceof Error ? healthQuery.error.message : "Failed to load app state"}
102→      </div>
103→    );
104→  }
105→
106→  if (isAuthenticatedMode && healthQuery.data?.bootstrapStatus === "bootstrap_pending") {
107→    return <BootstrapPendingPage hasActiveInvite={healthQuery.data.bootstrapInviteActive} />;
108→  }
109→
110→  if (isAuthenticatedMode && !sessionQuery.data) {
111→    const next = encodeURIComponent(`${location.pathname}${location.search}`);
112→    return <Navigate to={`/auth?next=${next}`} replace />;
113→  }
114→
115→  return <Outlet />;
116→}
