 1→import { applyPendingMigrations, inspectMigrations } from "./client.js";
 2→import { resolveMigrationConnection } from "./migration-runtime.js";
 3→
 4→async function main(): Promise<void> {
 5→  const resolved = await resolveMigrationConnection();
 6→
 7→  console.log(`Migrating database via ${resolved.source}`);
 8→
 9→  try {
10→    const before = await inspectMigrations(resolved.connectionString);
11→    if (before.status === "upToDate") {
12→      console.log("No pending migrations");
13→      return;
14→    }
15→
16→    console.log(`Applying ${before.pendingMigrations.length} pending migration(s)...`);
17→    await applyPendingMigrations(resolved.connectionString);
18→
19→    const after = await inspectMigrations(resolved.connectionString);
20→    if (after.status !== "upToDate") {
21→      throw new Error(`Migrations incomplete: ${after.pendingMigrations.join(", ")}`);
22→    }
23→    console.log("Migrations complete");
24→  } finally {
25→    await resolved.stop();
26→  }
27→}
28→
29→await main();
