 84→function arraysEqual(a: string[], b: string[]): boolean {
 85→  if (a.length !== b.length) return false;
 86→  const sa = [...a].sort();
 87→  const sb = [...b].sort();
 88→  return sa.every((v, i) => v === sb[i]);
 89→}
