 95→function applyFilters(issues: Issue[], state: IssueViewState, currentUserId?: string | null): Issue[] {
 96→  let result = issues;
 97→  if (state.statuses.length > 0) result = result.filter((i) => state.statuses.includes(i.status));
 98→  if (state.priorities.length > 0) result = result.filter((i) => state.priorities.includes(i.priority));
 99→  if (state.assignees.length > 0) {
100→    result = result.filter((issue) => {
101→      for (const assignee of state.assignees) {
102→        if (assignee === "__unassigned" && !issue.assigneeAgentId && !issue.assigneeUserId) return true;
103→        if (assignee === "__me" && currentUserId && issue.assigneeUserId === currentUserId) return true;
104→        if (issue.assigneeAgentId === assignee) return true;
105→      }
106→      return false;
107→    });
108→  }
109→  if (state.labels.length > 0) result = result.filter((i) => (i.labelIds ?? []).some((id) => state.labels.includes(id)));
110→  if (state.projects.length > 0) result = result.filter((i) => i.projectId != null && state.projects.includes(i.projectId));
111→  return result;
112→}
113→
114→function sortIssues(issues: Issue[], state: IssueViewState): Issue[] {
115→  const sorted = [...issues];
116→  const dir = state.sortDir === "asc" ? 1 : -1;
117→  sorted.sort((a, b) => {
118→    switch (state.sortField) {
119→      case "status":
120→        return dir * (statusOrder.indexOf(a.status) - statusOrder.indexOf(b.status));
121→      case "priority":
122→        return dir * (priorityOrder.indexOf(a.priority) - priorityOrder.indexOf(b.priority));
123→      case "title":
124→        return dir * a.title.localeCompare(b.title);
125→      case "created":
126→        return dir * (new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime());
127→      case "updated":
128→        return dir * (new Date(a.updatedAt).getTime() - new Date(b.updatedAt).getTime());
129→      default:
130→        return 0;
131→    }
132→  });
133→  return sorted;
134→}
135→
136→function countActiveFilters(state: IssueViewState): number {
137→  let count = 0;
138→  if (state.statuses.length > 0) count++;
139→  if (state.priorities.length > 0) count++;
140→  if (state.assignees.length > 0) count++;
141→  if (state.labels.length > 0) count++;
142→  if (state.projects.length > 0) count++;
143→  return count;
144→}
