 30→function toError(error: unknown, fallbackMessage: string): Error {
 31→  if (error instanceof Error) return error;
 32→  if (error === undefined) return new Error(fallbackMessage);
 33→  if (typeof error === "string") return new Error(`${fallbackMessage}: ${error}`);
 34→
 35→  try {
 36→    return new Error(`${fallbackMessage}: ${JSON.stringify(error)}`);
 37→  } catch {
 38→    return new Error(`${fallbackMessage}: ${String(error)}`);
 39→  }
 40→}
