 42→function readRunningPostmasterPid(postmasterPidFile: string): number | null {
 43→  if (!existsSync(postmasterPidFile)) return null;
 44→  try {
 45→    const pid = Number(readFileSync(postmasterPidFile, "utf8").split("\n")[0]?.trim());
 46→    if (!Number.isInteger(pid) || pid <= 0) return null;
 47→    process.kill(pid, 0);
 48→    return pid;
 49→  } catch {
 50→    return null;
 51→  }
 52→}
 53→
 54→function readPidFilePort(postmasterPidFile: string): number | null {
 55→  if (!existsSync(postmasterPidFile)) return null;
 56→  try {
 57→    const lines = readFileSync(postmasterPidFile, "utf8").split("\n");
 58→    const port = Number(lines[3]?.trim());
 59→    return Number.isInteger(port) && port > 0 ? port : null;
 60→  } catch {
 61→    return null;
 62→  }
 63→}
 64→
 65→async function isPortInUse(port: number): Promise<boolean> {
 66→  return await new Promise((resolve) => {
 67→    const server = createServer();
 68→    server.unref();
 69→    server.once("error", (error: NodeJS.ErrnoException) => {
 70→      resolve(error.code === "EADDRINUSE");
 71→    });
 72→    server.listen(port, "127.0.0.1", () => {
 73→      server.close();
 74→      resolve(false);
 75→    });
 76→  });
 77→}
 78→
 79→async function findAvailablePort(startPort: number): Promise<number> {
 80→  const maxLookahead = 20;
 81→  let port = startPort;
 82→  for (let i = 0; i < maxLookahead; i += 1, port += 1) {
 83→    if (!(await isPortInUse(port))) return port;
 84→  }
 85→  throw new Error(
 86→    `Embedded PostgreSQL could not find a free port from ${startPort} to ${startPort + maxLookahead - 1}`,
 87→  );
 88→}
 89→
 90→async function loadEmbeddedPostgresCtor(): Promise<EmbeddedPostgresCtor> {
 91→  try {
 92→    const mod = await import("embedded-postgres");
 93→    return mod.default as EmbeddedPostgresCtor;
 94→  } catch {
 95→    throw new Error(
 96→      "Embedded PostgreSQL support requires dependency `embedded-postgres`. Reinstall dependencies and try again.",
 97→    );
 98→  }
 99→}
100→
101→async function ensureEmbeddedPostgresConnection(
102→  dataDir: string,
103→  preferredPort: number,
104→): Promise<MigrationConnection> {
105→  const EmbeddedPostgres = await loadEmbeddedPostgresCtor();
106→  const selectedPort = await findAvailablePort(preferredPort);
107→  const postmasterPidFile = path.resolve(dataDir, "postmaster.pid");
108→  const pgVersionFile = path.resolve(dataDir, "PG_VERSION");
109→  const runningPid = readRunningPostmasterPid(postmasterPidFile);
110→  const runningPort = readPidFilePort(postmasterPidFile);
111→  const preferredAdminConnectionString = `postgres://paperclip:paperclip@127.0.0.1:${preferredPort}/postgres`;
112→
113→  if (!runningPid && existsSync(pgVersionFile)) {
114→    try {
115→      const actualDataDir = await getPostgresDataDirectory(preferredAdminConnectionString);
116→      const matchesDataDir =
117→        typeof actualDataDir === "string" &&
118→        path.resolve(actualDataDir) === path.resolve(dataDir);
119→      if (!matchesDataDir) {
120→        throw new Error("reachable postgres does not use the expected embedded data directory");
121→      }
122→      await ensurePostgresDatabase(preferredAdminConnectionString, "paperclip");
123→      process.emitWarning(
124→        `Adopting an existing PostgreSQL instance on port ${preferredPort} for embedded data dir ${dataDir} because postmaster.pid is missing.`,
125→      );
126→      return {
127→        connectionString: `postgres://paperclip:paperclip@127.0.0.1:${preferredPort}/paperclip`,
128→        source: `embedded-postgres@${preferredPort}`,
129→        stop: async () => {},
130→      };
131→    } catch {
132→      // Fall through and attempt to start the configured embedded cluster.
133→    }
134→  }
135→
136→  if (runningPid) {
137→    const port = runningPort ?? preferredPort;
138→    const adminConnectionString = `postgres://paperclip:paperclip@127.0.0.1:${port}/postgres`;
139→    await ensurePostgresDatabase(adminConnectionString, "paperclip");
140→    return {
141→      connectionString: `postgres://paperclip:paperclip@127.0.0.1:${port}/paperclip`,
142→      source: `embedded-postgres@${port}`,
143→      stop: async () => {},
144→    };
145→  }
146→
147→  const instance = new EmbeddedPostgres({
148→    databaseDir: dataDir,
149→    user: "paperclip",
150→    password: "paperclip",
151→    port: selectedPort,
152→    persistent: true,
153→    initdbFlags: ["--encoding=UTF8", "--locale=C"],
154→    onLog: () => {},
155→    onError: () => {},
156→  });
157→
158→  if (!existsSync(path.resolve(dataDir, "PG_VERSION"))) {
159→    try {
160→      await instance.initialise();
161→    } catch (error) {
162→      throw toError(
163→        error,
164→        `Failed to initialize embedded PostgreSQL cluster in ${dataDir} on port ${selectedPort}`,
165→      );
166→    }
167→  }
168→  if (existsSync(postmasterPidFile)) {
169→    rmSync(postmasterPidFile, { force: true });
170→  }
171→  try {
172→    await instance.start();
173→  } catch (error) {
174→    throw toError(error, `Failed to start embedded PostgreSQL on port ${selectedPort}`);
175→  }
176→
177→  const adminConnectionString = `postgres://paperclip:paperclip@127.0.0.1:${selectedPort}/postgres`;
178→  await ensurePostgresDatabase(adminConnectionString, "paperclip");
179→
180→  return {
181→    connectionString: `postgres://paperclip:paperclip@127.0.0.1:${selectedPort}/paperclip`,
182→    source: `embedded-postgres@${selectedPort}`,
183→    stop: async () => {
184→      await instance.stop();
185→    },
186→  };
187→}
188→
189→export async function resolveMigrationConnection(): Promise<MigrationConnection> {
190→  const target = resolveDatabaseTarget();
191→  if (target.mode === "postgres") {
192→    return {
193→      connectionString: target.connectionString,
194→      source: target.source,
195→      stop: async () => {},
196→    };
197→  }
198→
199→  return ensureEmbeddedPostgresConnection(target.dataDir, target.port);
200→}
