124→  const adapterConfig: Record<string, unknown> = {};
125→  if (input.modelOverride) adapterConfig.model = input.modelOverride;
126→  if (input.thinkingEffortOverride) {
127→    if (adapterType === "codex_local") {
128→      adapterConfig.modelReasoningEffort = input.thinkingEffortOverride;
129→    } else if (adapterType === "opencode_local") {
130→      adapterConfig.variant = input.thinkingEffortOverride;
131→    } else if (adapterType === "claude_local") {
132→      adapterConfig.effort = input.thinkingEffortOverride;
133→    } else if (adapterType === "opencode_local") {
134→      adapterConfig.variant = input.thinkingEffortOverride;
135→    }
136→  }
