140→
141→  const overrides: Record<string, unknown> = {};
142→  if (Object.keys(adapterConfig).length > 0) {
143→    overrides.adapterConfig = adapterConfig;
144→  }
145→  return Object.keys(overrides).length > 0 ? overrides : null;
146→}
