 33→  tone: ToastTone;
 34→  ttlMs: number;
 35→  action?: ToastAction;
 36→  createdAt: number;
 37→}
 38→
 39→interface ToastContextValue {
 40→  toasts: ToastItem[];
 41→  pushToast: (input: ToastInput) => string | null;
 42→  dismissToast: (id: string) => void;
 43→  clearToasts: () => void;
 44→}
 45→
 46→const DEFAULT_TTL_BY_TONE: Record<ToastTone, number> = {
 47→  info: 4000,
 48→  success: 3500,
 49→  warn: 8000,
 50→  error: 10000,
 51→};
 52→const MIN_TTL_MS = 1500;
 53→const MAX_TTL_MS = 15000;
 54→const MAX_TOASTS = 5;
 55→const DEDUPE_WINDOW_MS = 3500;
 56→const DEDUPE_MAX_AGE_MS = 20000;
 57→
 58→const ToastContext = createContext<ToastContextValue | null>(null);
 59→
 60→function normalizeTtl(value: number | undefined, tone: ToastTone) {
 61→  const fallback = DEFAULT_TTL_BY_TONE[tone];
 62→  if (typeof value !== "number" || !Number.isFinite(value)) return fallback;
 63→  return Math.max(MIN_TTL_MS, Math.min(MAX_TTL_MS, Math.floor(value)));
 64→}
 65→
 66→function generateToastId() {
 67→  return `toast_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
 68→}
 69→
 70→export function ToastProvider({ children }: { children: ReactNode }) {
 71→  const [toasts, setToasts] = useState<ToastItem[]>([]);
 72→  const timersRef = useRef(new Map<string, number>());
 73→  const dedupeRef = useRef(new Map<string, number>());
 74→
 75→  const clearTimer = useCallback((id: string) => {
 76→    const handle = timersRef.current.get(id);
 77→    if (handle !== undefined) {
 78→      window.clearTimeout(handle);
 79→      timersRef.current.delete(id);
 80→    }
 81→  }, []);
 82→
 83→  const dismissToast = useCallback(
 84→    (id: string) => {
 85→      clearTimer(id);
 86→      setToasts((prev) => prev.filter((toast) => toast.id !== id));
 87→    },
 88→    [clearTimer],
 89→  );
 90→
 91→  const clearToasts = useCallback(() => {
 92→    for (const handle of timersRef.current.values()) {
 93→      window.clearTimeout(handle);
 94→    }
 95→    timersRef.current.clear();
 96→    setToasts([]);
 97→  }, []);
 98→
 99→  const pushToast = useCallback(
100→    (input: ToastInput) => {
101→      const now = Date.now();
102→      const tone = input.tone ?? "info";
103→      const ttlMs = normalizeTtl(input.ttlMs, tone);
104→      const dedupeKey =
105→        input.dedupeKey ?? input.id ?? `${tone}|${input.title}|${input.body ?? ""}|${input.action?.href ?? ""}`;
106→
107→      for (const [key, ts] of dedupeRef.current.entries()) {
108→        if (now - ts > DEDUPE_MAX_AGE_MS) {
109→          dedupeRef.current.delete(key);
110→        }
111→      }
112→
113→      const lastSeen = dedupeRef.current.get(dedupeKey);
114→      if (lastSeen && now - lastSeen < DEDUPE_WINDOW_MS) {
115→        return null;
116→      }
117→      dedupeRef.current.set(dedupeKey, now);
118→
119→      const id = input.id ?? generateToastId();
120→      clearTimer(id);
121→
122→      setToasts((prev) => {
123→        const nextToast: ToastItem = {
124→          id,
125→          title: input.title,
126→          body: input.body,
127→          tone,
128→          ttlMs,
129→          action: input.action,
130→          createdAt: now,
131→        };
132→
133→        const withoutCurrent = prev.filter((toast) => toast.id !== id);
134→        return [nextToast, ...withoutCurrent].slice(0, MAX_TOASTS);
135→      });
136→
137→      const timeout = window.setTimeout(() => {
138→        dismissToast(id);
139→      }, ttlMs);
140→      timersRef.current.set(id, timeout);
141→      return id;
142→    },
143→    [clearTimer, dismissToast],
144→  );
145→
146→  useEffect(() => () => {
147→    for (const handle of timersRef.current.values()) {
148→      window.clearTimeout(handle);
149→    }
150→    timersRef.current.clear();
151→  }, []);
152→
153→  const value = useMemo<ToastContextValue>(
154→    () => ({
155→      toasts,
156→      pushToast,
157→      dismissToast,
158→      clearToasts,
159→    }),
160→    [toasts, pushToast, dismissToast, clearToasts],
161→  );
162→
163→  return <ToastContext.Provider value={value}>{children}</ToastContext.Provider>;
164→}
165→
166→export function useToast() {
167→  const context = useContext(ToastContext);
168→  if (!context) {
169→    throw new Error("useToast must be used within a ToastProvider");
170→  }
171→  return context;
172→}
