  1→import { existsSync, readFileSync } from "node:fs";
  2→import os from "node:os";
  3→import path from "node:path";
  4→
  5→const DEFAULT_INSTANCE_ID = "default";
  6→const CONFIG_BASENAME = "config.json";
  7→const ENV_BASENAME = ".env";
  8→const INSTANCE_ID_RE = /^[a-zA-Z0-9_-]+$/;
  9→
 10→type PartialConfig = {
 11→  database?: {
 12→    mode?: "embedded-postgres" | "postgres";
 13→    connectionString?: string;
 14→    embeddedPostgresDataDir?: string;
 15→    embeddedPostgresPort?: number;
 16→    pgliteDataDir?: string;
 17→    pglitePort?: number;
 18→  };
 19→};
 20→
 21→export type ResolvedDatabaseTarget =
 22→  | {
 23→      mode: "postgres";
 24→      connectionString: string;
 25→      source: "DATABASE_URL" | "paperclip-env" | "config.database.connectionString";
 26→      configPath: string;
 27→      envPath: string;
 28→    }
 29→  | {
 30→      mode: "embedded-postgres";
 31→      dataDir: string;
 32→      port: number;
 33→      source: `embedded-postgres@${number}`;
 34→      configPath: string;
 35→      envPath: string;
 36→    };
 37→
 38→function expandHomePrefix(value: string): string {
 39→  if (value === "~") return os.homedir();
 40→  if (value.startsWith("~/")) return path.resolve(os.homedir(), value.slice(2));
 41→  return value;
 42→}
 43→
 44→function resolvePaperclipHomeDir(): string {
 45→  const envHome = process.env.PAPERCLIP_HOME?.trim();
 46→  if (envHome) return path.resolve(expandHomePrefix(envHome));
 47→  return path.resolve(os.homedir(), ".paperclip");
 48→}
 49→
 50→function resolvePaperclipInstanceId(): string {
 51→  const raw = process.env.PAPERCLIP_INSTANCE_ID?.trim() || DEFAULT_INSTANCE_ID;
 52→  if (!INSTANCE_ID_RE.test(raw)) {
 53→    throw new Error(`Invalid PAPERCLIP_INSTANCE_ID '${raw}'.`);
 54→  }
 55→  return raw;
 56→}
 57→
 58→function resolveDefaultConfigPath(): string {
 59→  return path.resolve(
 60→    resolvePaperclipHomeDir(),
 61→    "instances",
 62→    resolvePaperclipInstanceId(),
 63→    CONFIG_BASENAME,
 64→  );
 65→}
 66→
 67→function resolveDefaultEmbeddedPostgresDir(): string {
 68→  return path.resolve(resolvePaperclipHomeDir(), "instances", resolvePaperclipInstanceId(), "db");
 69→}
 70→
 71→function resolveHomeAwarePath(value: string): string {
 72→  return path.resolve(expandHomePrefix(value));
 73→}
 74→
 75→function findConfigFileFromAncestors(startDir: string): string | null {
 76→  let currentDir = path.resolve(startDir);
 77→
 78→  while (true) {
 79→    const candidate = path.resolve(currentDir, ".paperclip", CONFIG_BASENAME);
 80→    if (existsSync(candidate)) return candidate;
 81→
 82→    const nextDir = path.resolve(currentDir, "..");
 83→    if (nextDir === currentDir) return null;
 84→    currentDir = nextDir;
 85→  }
 86→}
 87→
 88→function resolvePaperclipConfigPath(): string {
 89→  if (process.env.PAPERCLIP_CONFIG?.trim()) {
 90→    return path.resolve(process.env.PAPERCLIP_CONFIG.trim());
 91→  }
 92→  return findConfigFileFromAncestors(process.cwd()) ?? resolveDefaultConfigPath();
 93→}
 94→
 95→function resolvePaperclipEnvPath(configPath: string): string {
 96→  return path.resolve(path.dirname(configPath), ENV_BASENAME);
 97→}
 98→
 99→function parseEnvFile(contents: string): Record<string, string> {
100→  const entries: Record<string, string> = {};
101→
102→  for (const rawLine of contents.split(/\r?\n/)) {
103→    const line = rawLine.trim();
104→    if (!line || line.startsWith("#")) continue;
105→
106→    const match = rawLine.match(/^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)\s*$/);
107→    if (!match) continue;
108→
109→    const [, key, rawValue] = match;
110→    const value = rawValue.trim();
111→    if (!value) {
112→      entries[key] = "";
113→      continue;
114→    }
115→
116→    if (
117→      (value.startsWith("\"") && value.endsWith("\"")) ||
118→      (value.startsWith("'") && value.endsWith("'"))
119→    ) {
120→      entries[key] = value.slice(1, -1);
121→      continue;
122→    }
123→
124→    entries[key] = value.replace(/\s+#.*$/, "").trim();
125→  }
126→
127→  return entries;
128→}
129→
130→function readEnvEntries(envPath: string): Record<string, string> {
131→  if (!existsSync(envPath)) return {};
132→  return parseEnvFile(readFileSync(envPath, "utf8"));
133→}
134→
135→function migrateLegacyConfig(raw: unknown): PartialConfig | null {
136→  if (typeof raw !== "object" || raw === null || Array.isArray(raw)) return null;
137→
138→  const config = { ...(raw as Record<string, unknown>) };
139→  const databaseRaw = config.database;
140→  if (typeof databaseRaw !== "object" || databaseRaw === null || Array.isArray(databaseRaw)) {
141→    return config;
142→  }
143→
144→  const database = { ...(databaseRaw as Record<string, unknown>) };
145→  if (database.mode === "pglite") {
146→    database.mode = "embedded-postgres";
147→
148→    if (
149→      typeof database.embeddedPostgresDataDir !== "string" &&
150→      typeof database.pgliteDataDir === "string"
151→    ) {
152→      database.embeddedPostgresDataDir = database.pgliteDataDir;
153→    }
154→    if (
155→      typeof database.embeddedPostgresPort !== "number" &&
156→      typeof database.pglitePort === "number" &&
157→      Number.isFinite(database.pglitePort)
158→    ) {
159→      database.embeddedPostgresPort = database.pglitePort;
160→    }
161→  }
162→
163→  config.database = database;
164→  return config as PartialConfig;
165→}
166→
167→function asPositiveInt(value: unknown): number | null {
168→  if (typeof value !== "number" || !Number.isFinite(value)) return null;
169→  const rounded = Math.trunc(value);
170→  return rounded > 0 ? rounded : null;
171→}
172→
173→function readConfig(configPath: string): PartialConfig | null {
174→  if (!existsSync(configPath)) return null;
175→
176→  let parsed: unknown;
177→  try {
178→    parsed = JSON.parse(readFileSync(configPath, "utf8"));
179→  } catch (err) {
180→    throw new Error(
181→      `Failed to parse config at ${configPath}: ${err instanceof Error ? err.message : String(err)}`,
182→    );
183→  }
184→
185→  const migrated = migrateLegacyConfig(parsed);
186→  if (migrated === null || typeof migrated !== "object" || Array.isArray(migrated)) {
187→    throw new Error(`Invalid config at ${configPath}: expected a JSON object`);
188→  }
189→
190→  const database =
191→    typeof migrated.database === "object" &&
192→    migrated.database !== null &&
193→    !Array.isArray(migrated.database)
194→      ? migrated.database
195→      : undefined;
196→
197→  return {
198→    database: database
199→      ? {
200→          mode: database.mode === "postgres" ? "postgres" : "embedded-postgres",
201→          connectionString:
202→            typeof database.connectionString === "string" ? database.connectionString : undefined,
203→          embeddedPostgresDataDir:
204→            typeof database.embeddedPostgresDataDir === "string"
205→              ? database.embeddedPostgresDataDir
206→              : undefined,
207→          embeddedPostgresPort: asPositiveInt(database.embeddedPostgresPort) ?? undefined,
208→          pgliteDataDir: typeof database.pgliteDataDir === "string" ? database.pgliteDataDir : undefined,
209→          pglitePort: asPositiveInt(database.pglitePort) ?? undefined,
210→        }
211→      : undefined,
212→  };
213→}
214→
215→export function resolveDatabaseTarget(): ResolvedDatabaseTarget {
216→  const configPath = resolvePaperclipConfigPath();
217→  const envPath = resolvePaperclipEnvPath(configPath);
218→  const envEntries = readEnvEntries(envPath);
219→
220→  const envUrl = process.env.DATABASE_URL?.trim();
221→  if (envUrl) {
222→    return {
223→      mode: "postgres",
224→      connectionString: envUrl,
225→      source: "DATABASE_URL",
226→      configPath,
227→      envPath,
228→    };
229→  }
230→
231→  const fileEnvUrl = envEntries.DATABASE_URL?.trim();
232→  if (fileEnvUrl) {
233→    return {
234→      mode: "postgres",
235→      connectionString: fileEnvUrl,
236→      source: "paperclip-env",
237→      configPath,
238→      envPath,
239→    };
240→  }
241→
242→  const config = readConfig(configPath);
243→  const connectionString = config?.database?.connectionString?.trim();
244→  if (config?.database?.mode === "postgres" && connectionString) {
245→    return {
246→      mode: "postgres",
247→      connectionString,
248→      source: "config.database.connectionString",
249→      configPath,
250→      envPath,
251→    };
252→  }
253→
254→  const port = config?.database?.embeddedPostgresPort ?? 54329;
255→  const dataDir = resolveHomeAwarePath(
256→    config?.database?.embeddedPostgresDataDir ?? resolveDefaultEmbeddedPostgresDir(),
257→  );
258→
259→  return {
260→    mode: "embedded-postgres",
261→    dataDir,
262→    port,
263→    source: `embedded-postgres@${port}`,
264→    configPath,
265→    envPath,
266→  };
267→}
