1299→// ui/src/hooks/usePermission.ts
1300→import { useCurrentUser } from "./useCurrentUser";
1301→import { ROLE_PERMISSIONS, type UserRole } from "@paperclipai/shared";
1302→
1303→export function usePermission(permission: string): boolean {
1304→  const { data: user } = useCurrentUser();
1305→  if (!user?.role) return false;
1306→  const role = user.role as UserRole;
1307→  return ROLE_PERMISSIONS[role]?.includes(permission) ?? false;
