 99→        next();
100→        return;
101→      }
102→    }
103→
104→    const tokenHash = hashToken(token);
105→    const key = await db
106→      .select()
107→      .from(agentApiKeys)
108→      .where(and(eq(agentApiKeys.keyHash, tokenHash), isNull(agentApiKeys.revokedAt)))
109→      .then((rows) => rows[0] ?? null);
110→
111→    if (!key) {
112→      const claims = verifyLocalAgentJwt(token);
113→      if (!claims) {
114→        next();
115→        return;
116→      }
117→
118→      const agentRecord = await db
119→        .select()
120→        .from(agents)
121→        .where(eq(agents.id, claims.sub))
122→        .then((rows) => rows[0] ?? null);
123→
124→      if (!agentRecord || agentRecord.companyId !== claims.company_id) {
125→        next();
126→        return;
127→      }
128→
129→      if (agentRecord.status === "terminated" || agentRecord.status === "pending_approval") {
130→        next();
131→        return;
132→      }
133→
134→      req.actor = {
135→        type: "agent",
136→        agentId: claims.sub,
137→        companyId: claims.company_id,
138→        keyId: undefined,
139→        runId: runIdHeader || claims.run_id || undefined,
140→        source: "agent_jwt",
141→      };
142→      next();
143→      return;
144→    }
145→
146→    await db
147→      .update(agentApiKeys)
148→      .set({ lastUsedAt: new Date() })
149→      .where(eq(agentApiKeys.id, key.id));
150→
151→    const agentRecord = await db
152→      .select()
153→      .from(agents)
154→      .where(eq(agents.id, key.agentId))
155→      .then((rows) => rows[0] ?? null);
156→
157→    if (!agentRecord || agentRecord.status === "terminated" || agentRecord.status === "pending_approval") {
158→      next();
159→      return;
160→    }
161→
162→    req.actor = {
