 1→import type { Request } from "express";
 2→import { forbidden, unauthorized } from "../errors.js";
 3→
 4→export function assertBoard(req: Request) {
 5→  if (req.actor.type !== "board") {
 6→    throw forbidden("Board access required");
 7→  }
 8→}
 9→
10→export function assertInstanceAdmin(req: Request) {
11→  assertBoard(req);
12→  if (req.actor.source === "local_implicit" || req.actor.isInstanceAdmin) {
13→    return;
14→  }
15→  throw forbidden("Instance admin access required");
16→}
17→
18→export function assertCompanyAccess(req: Request, companyId: string) {
19→  if (req.actor.type === "none") {
20→    throw unauthorized();
21→  }
22→  if (req.actor.type === "agent" && req.actor.companyId !== companyId) {
23→    throw forbidden("Agent key cannot access another company");
24→  }
25→  if (req.actor.type === "board" && req.actor.source !== "local_implicit" && !req.actor.isInstanceAdmin) {
26→    const allowedCompanies = req.actor.companyIds ?? [];
27→    if (!allowedCompanies.includes(companyId)) {
28→      throw forbidden("User does not have access to this company");
29→    }
30→  }
31→}
32→
33→export function getActorInfo(req: Request) {
34→  if (req.actor.type === "none") {
35→    throw unauthorized();
36→  }
37→  if (req.actor.type === "agent") {
38→    return {
39→      actorType: "agent" as const,
40→      actorId: req.actor.agentId ?? "unknown-agent",
41→      agentId: req.actor.agentId ?? null,
42→      runId: req.actor.runId ?? null,
43→    };
44→  }
45→
46→  return {
47→    actorType: "user" as const,
48→    actorId: req.actor.userId ?? "board",
49→    agentId: null,
50→    runId: req.actor.runId ?? null,
51→  };
52→}
