  9→  instanceUserRoles,
 10→} from "@paperclipai/db";
 11→import { logger } from "../middleware/logger.js";
 12→import { resolveProjectRoot, resolveAgentInstructionsDir } from "../home-paths.js";
 13→import { loadDefaultAgentInstructionsBundle } from "./default-agent-instructions.js";
 14→
 15→export interface BootstrapResult {
 16→  action: "created_company" | "assigned_to_company" | "noop";
 17→  companyId?: string;
 18→}
