 10→type MembershipRow = typeof companyMemberships.$inferSelect;
 11→type GrantInput = {
 12→  permissionKey: PermissionKey;
 13→  scope?: Record<string, unknown> | null;
 14→};
 15→
 16→export function accessService(db: Db) {
 17→  async function isInstanceAdmin(userId: string | null | undefined): Promise<boolean> {
 18→    if (!userId) return false;
 19→    const row = await db
 20→      .select({ id: instanceUserRoles.id })
 21→      .from(instanceUserRoles)
 22→      .where(and(eq(instanceUserRoles.userId, userId), eq(instanceUserRoles.role, "instance_admin")))
 23→      .then((rows) => rows[0] ?? null);
 24→    return Boolean(row);
 25→  }
 26→
 27→  async function getMembership(
 28→    companyId: string,
 29→    principalType: PrincipalType,
 30→    principalId: string,
 31→  ): Promise<MembershipRow | null> {
 32→    return db
 33→      .select()
 34→      .from(companyMemberships)
 35→      .where(
 36→        and(
 37→          eq(companyMemberships.companyId, companyId),
 38→          eq(companyMemberships.principalType, principalType),
 39→          eq(companyMemberships.principalId, principalId),
 40→        ),
 41→      )
 42→      .then((rows) => rows[0] ?? null);
 43→  }
 44→
 45→  async function hasPermission(
 46→    companyId: string,
 47→    principalType: PrincipalType,
 48→    principalId: string,
 49→    permissionKey: PermissionKey,
 50→  ): Promise<boolean> {
 51→    const membership = await getMembership(companyId, principalType, principalId);
 52→    if (!membership || membership.status !== "active") return false;
 53→    const grant = await db
 54→      .select({ id: principalPermissionGrants.id })
 55→      .from(principalPermissionGrants)
 56→      .where(
 57→        and(
 58→          eq(principalPermissionGrants.companyId, companyId),
 59→          eq(principalPermissionGrants.principalType, principalType),
 60→          eq(principalPermissionGrants.principalId, principalId),
 61→          eq(principalPermissionGrants.permissionKey, permissionKey),
 62→        ),
 63→      )
 64→      .then((rows) => rows[0] ?? null);
 65→    return Boolean(grant);
 66→  }
 67→
 68→  async function canUser(
 69→    companyId: string,
 70→    userId: string | null | undefined,
 71→    permissionKey: PermissionKey,
 72→  ): Promise<boolean> {
 73→    if (!userId) return false;
 74→    if (await isInstanceAdmin(userId)) return true;
 75→    return hasPermission(companyId, "user", userId, permissionKey);
 76→  }
 77→
 78→  async function listMembers(companyId: string) {
 79→    return db
 80→      .select()
 81→      .from(companyMemberships)
 82→      .where(eq(companyMemberships.companyId, companyId))
 83→      .orderBy(sql`${companyMemberships.createdAt} desc`);
 84→  }
 85→
 86→  async function listActiveUserMemberships(companyId: string) {
 87→    return db
 88→      .select()
 89→      .from(companyMemberships)
 90→      .where(
 91→        and(
 92→          eq(companyMemberships.companyId, companyId),
 93→          eq(companyMemberships.principalType, "user"),
 94→          eq(companyMemberships.status, "active"),
 95→        ),
 96→      )
 97→      .orderBy(sql`${companyMemberships.createdAt} asc`);
 98→  }
 99→
100→  async function setMemberPermissions(
101→    companyId: string,
102→    memberId: string,
103→    grants: GrantInput[],
104→    grantedByUserId: string | null,
105→  ) {
106→    const member = await db
107→      .select()
108→      .from(companyMemberships)
109→      .where(and(eq(companyMemberships.companyId, companyId), eq(companyMemberships.id, memberId)))
110→      .then((rows) => rows[0] ?? null);
111→    if (!member) return null;
112→
113→    await db.transaction(async (tx) => {
114→      await tx
115→        .delete(principalPermissionGrants)
116→        .where(
117→          and(
118→            eq(principalPermissionGrants.companyId, companyId),
119→            eq(principalPermissionGrants.principalType, member.principalType),
120→            eq(principalPermissionGrants.principalId, member.principalId),
121→          ),
122→        );
123→      if (grants.length > 0) {
124→        await tx.insert(principalPermissionGrants).values(
125→          grants.map((grant) => ({
126→            companyId,
127→            principalType: member.principalType,
128→            principalId: member.principalId,
129→            permissionKey: grant.permissionKey,
130→            scope: grant.scope ?? null,
131→            grantedByUserId,
132→            createdAt: new Date(),
133→            updatedAt: new Date(),
134→          })),
135→        );
136→      }
137→    });
138→
139→    return member;
140→  }
