142→  async function promoteInstanceAdmin(userId: string) {
143→    const existing = await db
144→      .select()
145→      .from(instanceUserRoles)
146→      .where(and(eq(instanceUserRoles.userId, userId), eq(instanceUserRoles.role, "instance_admin")))
147→      .then((rows) => rows[0] ?? null);
148→    if (existing) return existing;
149→    return db
150→      .insert(instanceUserRoles)
151→      .values({
152→        userId,
153→        role: "instance_admin",
154→      })
155→      .returning()
156→      .then((rows) => rows[0]);
157→  }
