159→  async function demoteInstanceAdmin(userId: string) {
160→    return db
161→      .delete(instanceUserRoles)
162→      .where(and(eq(instanceUserRoles.userId, userId), eq(instanceUserRoles.role, "instance_admin")))
163→      .returning()
164→      .then((rows) => rows[0] ?? null);
165→  }
166→
167→  async function listUserCompanyAccess(userId: string) {
168→    return db
169→      .select()
170→      .from(companyMemberships)
171→      .where(and(eq(companyMemberships.principalType, "user"), eq(companyMemberships.principalId, userId)))
172→      .orderBy(sql`${companyMemberships.createdAt} desc`);
173→  }
174→
175→  async function setUserCompanyAccess(userId: string, companyIds: string[]) {
176→    const existing = await listUserCompanyAccess(userId);
177→    const existingByCompany = new Map(existing.map((row) => [row.companyId, row]));
178→    const target = new Set(companyIds);
179→
180→    await db.transaction(async (tx) => {
181→      const toDelete = existing.filter((row) => !target.has(row.companyId)).map((row) => row.id);
182→      if (toDelete.length > 0) {
183→        await tx.delete(companyMemberships).where(inArray(companyMemberships.id, toDelete));
184→      }
185→
186→      for (const companyId of target) {
187→        if (existingByCompany.has(companyId)) continue;
188→        await tx.insert(companyMemberships).values({
189→          companyId,
190→          principalType: "user",
191→          principalId: userId,
192→          status: "active",
193→          membershipRole: "member",
194→        });
195→      }
196→    });
197→
198→    return listUserCompanyAccess(userId);
199→  }
200→
201→  async function ensureMembership(
202→    companyId: string,
203→    principalType: PrincipalType,
204→    principalId: string,
205→    membershipRole: string | null = "member",
206→    status: "pending" | "active" | "suspended" = "active",
207→  ) {
208→    const existing = await getMembership(companyId, principalType, principalId);
209→    if (existing) {
210→      if (existing.status !== status || existing.membershipRole !== membershipRole) {
211→        const updated = await db
212→          .update(companyMemberships)
213→          .set({ status, membershipRole, updatedAt: new Date() })
214→          .where(eq(companyMemberships.id, existing.id))
215→          .returning()
216→          .then((rows) => rows[0] ?? null);
217→        return updated ?? existing;
218→      }
219→      return existing;
220→    }
221→
222→    return db
223→      .insert(companyMemberships)
224→      .values({
225→        companyId,
226→        principalType,
227→        principalId,
228→        status,
229→        membershipRole,
230→      })
231→      .returning()
232→      .then((rows) => rows[0]);
233→  }
