244→        .delete(principalPermissionGrants)
245→        .where(
246→          and(
247→            eq(principalPermissionGrants.companyId, companyId),
248→            eq(principalPermissionGrants.principalType, principalType),
249→            eq(principalPermissionGrants.principalId, principalId),
250→          ),
251→        );
252→      if (grants.length === 0) return;
253→      await tx.insert(principalPermissionGrants).values(
254→        grants.map((grant) => ({
255→          companyId,
256→          principalType,
257→          principalId,
258→          permissionKey: grant.permissionKey,
259→          scope: grant.scope ?? null,
260→          grantedByUserId,
261→          createdAt: new Date(),
262→          updatedAt: new Date(),
263→        })),
264→      );
265→    });
266→  }
