268→  async function copyActiveUserMemberships(sourceCompanyId: string, targetCompanyId: string) {
269→    const sourceMemberships = await listActiveUserMemberships(sourceCompanyId);
270→    for (const membership of sourceMemberships) {
271→      await ensureMembership(
