299→
300→  async function setPrincipalPermission(
301→    companyId: string,
302→    principalType: PrincipalType,
303→    principalId: string,
304→    permissionKey: PermissionKey,
305→    enabled: boolean,
306→    grantedByUserId: string | null,
307→    scope: Record<string, unknown> | null = null,
308→  ) {
309→    if (!enabled) {
310→      await db
311→        .delete(principalPermissionGrants)
312→        .where(
313→          and(
314→            eq(principalPermissionGrants.companyId, companyId),
315→            eq(principalPermissionGrants.principalType, principalType),
316→            eq(principalPermissionGrants.principalId, principalId),
317→            eq(principalPermissionGrants.permissionKey, permissionKey),
318→          ),
