    "skills:read",
    "approvals:read",
    "goals:read",
    "projects:read",
    "routines:read",
    "activity:read",
  ],
} as const;

/** Check if a role has a specific permission. */
export function hasRolePermission(role: UserRole, permission: string): boolean {
  return ROLE_PERMISSIONS[role]?.includes(permission) ?? false;
}
