499→import { hasRolePermission, type UserRole } from "@paperclipai/shared";
500→
501→export function requirePermission(req: Request, permission: string) {
502→  // local_trusted mode bypasses RBAC
503→  if (req.actor.source === "local_implicit") return;
504→
505→  // Agent actors use assertCompanyAccess, not RBAC
506→  if (req.actor.type === "agent") return;
507→
508→  // Must be a board actor
509→  if (req.actor.type !== "board") {
510→    throw forbidden("Board access required");
511→  }
512→
513→  if (!hasRolePermission(req.actor.role as UserRole, permission)) {
514→    throw forbidden("Insufficient permissions");
515→  }
516→}
