import { test, expect, type Page } from "@playwright/test";

const BASE = "http://127.0.0.1:3100";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

async function signUp(page: Page, name: string, email: string, password: string) {
  await page.goto(`${BASE}/auth`);
  // Click "Create one" to switch to sign-up form
  const createBtn = page.getByRole("button", { name: "Create one" });
  if (await createBtn.isVisible({ timeout: 3000 }).catch(() => false)) {
    await createBtn.click();
  }
  await page.getByRole("textbox", { name: "Name" }).fill(name);
  await page.getByRole("textbox", { name: "Email" }).fill(email);
  await page.getByRole("textbox", { name: "Password" }).fill(password);
  await page.getByRole("button", { name: "Create Account" }).click();
  // Wait for redirect to dashboard
  await expect(page).not.toHaveURL(/\/auth/, { timeout: 15000 });
}

async function signIn(page: Page, email: string, password: string) {
  await page.goto(`${BASE}/auth`);
  await page.locator('input[type="email"]').fill(email);
  await page.locator('input[type="password"]').fill(password);
  await page.getByRole("button", { name: "Sign In" }).click();
  await expect(page).not.toHaveURL(/\/auth/, { timeout: 15000 });
}

async function signOut(page: Page) {
  // Clear session via API
  await page.evaluate(() => fetch("/api/auth/sign-out", { method: "POST", credentials: "include" }));
}

async function apiGet(page: Page, path: string) {
  const res = await page.request.get(`${BASE}/api${path}`);
  return { status: res.status(), body: await res.json().catch(() => null) };
}

async function apiPost(page: Page, path: string, body: Record<string, unknown>) {
  const res = await page.request.post(`${BASE}/api${path}`, { data: body });
  return { status: res.status(), body: await res.json().catch(() => null) };
}

async function apiPatch(page: Page, path: string, body: Record<string, unknown>) {
  const res = await page.request.patch(`${BASE}/api${path}`, { data: body });
  return { status: res.status(), body: await res.json().catch(() => null) };
}

async function apiDelete(page: Page, path: string) {
  const res = await page.request.delete(`${BASE}/api${path}`);
  return { status: res.status(), body: await res.text().catch(() => null) };
}

