import { test, expect, type Page } from "@playwright/test";

const BASE = "http://127.0.0.1:3100";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

async function signUp(page: Page, name: string, email: string, password: string) {
  await page.goto(`${BASE}/auth`);
  // Click "Create one" to switch to sign-up form
  const createBtn = page.getByRole("button", { name: "Create one" });
  if (await createBtn.isVisible({ timeout: 3000 }).catch(() => false)) {
    await createBtn.click();
  }
  await page.getByRole("textbox", { name: "Name" }).fill(name);
  await page.getByRole("textbox", { name: "Email" }).fill(email);
  await page.getByRole("textbox", { name: "Password" }).fill(password);
  await page.getByRole("button", { name: "Create Account" }).click();
  // Wait for redirect to dashboard
  await expect(page).not.toHaveURL(/\/auth/, { timeout: 15000 });
}

async function signIn(page: Page, email: string, password: string) {
  await page.goto(`${BASE}/auth`);
  await page.locator('input[type="email"]').fill(email);
  await page.locator('input[type="password"]').fill(password);
  await page.getByRole("button", { name: "Sign In" }).click();
  await expect(page).not.toHaveURL(/\/auth/, { timeout: 15000 });
}

async function signOut(page: Page) {
  // Clear session via API
  await page.evaluate(() => fetch("/api/auth/sign-out", { method: "POST", credentials: "include" }));
}

async function apiGet(page: Page, path: string) {
  const res = await page.request.get(`${BASE}/api${path}`);
  return { status: res.status(), body: await res.json().catch(() => null) };
}

async function apiPost(page: Page, path: string, body: Record<string, unknown>) {
  const res = await page.request.post(`${BASE}/api${path}`, { data: body });
  return { status: res.status(), body: await res.json().catch(() => null) };
}

async function apiPatch(page: Page, path: string, body: Record<string, unknown>) {
  const res = await page.request.patch(`${BASE}/api${path}`, { data: body });
  return { status: res.status(), body: await res.json().catch(() => null) };
}

async function apiDelete(page: Page, path: string) {
  const res = await page.request.delete(`${BASE}/api${path}`);
  return { status: res.status(), body: await res.text().catch(() => null) };
}

// ---------------------------------------------------------------------------
// Test Data
// ---------------------------------------------------------------------------

const SUPERADMIN = { name: "Super Admin", email: "superadmin@rbac.test", password: "Super1234!" };
const ADMIN_USER = { name: "Admin User", email: "admin@rbac.test", password: "Admin1234!" };
const NORMAL_USER = { name: "Normal User", email: "user@rbac.test", password: "User1234!" };
const GUEST_USER = { name: "Guest User", email: "guest@rbac.test", password: "Guest1234!" };

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

test.describe.serial("RBAC Full E2E", () => {
  let companyId: string;

  test("1. Superadmin: sign up (first user) and verify role", async ({ page }) => {
    await signUp(page, SUPERADMIN.name, SUPERADMIN.email, SUPERADMIN.password);

    const me = await apiGet(page, "/users/me");
    expect(me.status).toBe(200);
    expect(me.body.role).toBe("superadmin");
    expect(me.body.name).toBe(SUPERADMIN.name);

    // Get company ID
    const companies = await apiGet(page, "/companies");
    expect(companies.status).toBe(200);
    expect(companies.body.length).toBeGreaterThan(0);
    companyId = companies.body[0].id;
  });

  test("2. Superadmin: create admin user via API", async ({ page }) => {
    await signIn(page, SUPERADMIN.email, SUPERADMIN.password);

    const result = await apiPost(page, "/users", {
      name: ADMIN_USER.name,
      email: ADMIN_USER.email,
      password: ADMIN_USER.password,
      role: "admin",
      companyIds: [companyId],
    });
    expect(result.status).toBe(201);
    expect(result.body.role).toBe("admin");
    expect(result.body.companies).toHaveLength(1);
  });

  test("3. Superadmin: create normal user via API", async ({ page }) => {
    await signIn(page, SUPERADMIN.email, SUPERADMIN.password);

    const result = await apiPost(page, "/users", {
      name: NORMAL_USER.name,
      email: NORMAL_USER.email,
      password: NORMAL_USER.password,
      role: "user",
      companyIds: [companyId],
    });
    expect(result.status).toBe(201);
    expect(result.body.role).toBe("user");
  });

  test("4. Superadmin: create guest user via API", async ({ page }) => {
    await signIn(page, SUPERADMIN.email, SUPERADMIN.password);

    const result = await apiPost(page, "/users", {
      name: GUEST_USER.name,
      email: GUEST_USER.email,
      password: GUEST_USER.password,
      role: "guest",
      companyIds: [companyId],
    });
    expect(result.status).toBe(201);
    expect(result.body.role).toBe("guest");
  });

  test("5. Superadmin: list users shows all 4 users", async ({ page }) => {
    await signIn(page, SUPERADMIN.email, SUPERADMIN.password);

    const result = await apiGet(page, "/users");
    expect(result.status).toBe(200);
    expect(result.body.length).toBe(4);

    const roles = result.body.map((u: any) => u.role).sort();
    expect(roles).toEqual(["admin", "guest", "superadmin", "user"]);
  });

  test("6. Superadmin: User Management page shows all users with actions", async ({ page }) => {
    await signIn(page, SUPERADMIN.email, SUPERADMIN.password);
    await page.goto(`${BASE}/PAP/company/settings/users`);

    await expect(page.getByRole("heading", { name: "User Management" })).toBeVisible();
    await expect(page.getByText(SUPERADMIN.email)).toBeVisible();
    await expect(page.getByText(ADMIN_USER.email)).toBeVisible();
    await expect(page.getByText(NORMAL_USER.email)).toBeVisible();
    await expect(page.getByText(GUEST_USER.email)).toBeVisible();
    await expect(page.getByRole("button", { name: "Create User" })).toBeVisible();
  });

  // -------------------------------------------------------------------------
  // Admin login & permission checks
  // -------------------------------------------------------------------------

  test("7. Admin: login and verify role", async ({ page }) => {
    await signIn(page, ADMIN_USER.email, ADMIN_USER.password);

    const me = await apiGet(page, "/users/me");
    expect(me.status).toBe(200);
    expect(me.body.role).toBe("admin");
  });

  test("8. Admin: can list users", async ({ page }) => {
    await signIn(page, ADMIN_USER.email, ADMIN_USER.password);

    const result = await apiGet(page, "/users");
    expect(result.status).toBe(200);
    expect(result.body.length).toBeGreaterThan(0);
  });

  test("9. Admin: can create user (only user/guest role)", async ({ page }) => {
    await signIn(page, ADMIN_USER.email, ADMIN_USER.password);

    // Can create guest
    const guestResult = await apiPost(page, "/users", {
      name: "Admin-Created Guest",
      email: "admin-guest@rbac.test",
      password: "Test1234!",
      role: "guest",
      companyIds: [companyId],
    });
    expect(guestResult.status).toBe(201);
    expect(guestResult.body.role).toBe("guest");

    // Cannot create admin
    const adminResult = await apiPost(page, "/users", {
      name: "Admin-Created Admin",
      email: "admin-admin@rbac.test",
      password: "Test1234!",
      role: "admin",
    });
    expect(adminResult.status).toBe(403);

    // Cannot create superadmin
    const superResult = await apiPost(page, "/users", {
      name: "Admin-Created Super",
      email: "admin-super@rbac.test",
      password: "Test1234!",
      role: "superadmin",
    });
    expect(superResult.status).toBe(403);
  });

  test("10. Admin: can create agent", async ({ page }) => {
    await signIn(page, ADMIN_USER.email, ADMIN_USER.password);

    const result = await apiPost(page, `/companies/${companyId}/agents`, {
      name: "Admin Test Agent",
      adapter: "claude-local",
    });
    // 201 = created, or 200 if the API returns differently
    expect([200, 201]).toContain(result.status);
  });

  test("11. Admin: can create issue", async ({ page }) => {
    await signIn(page, ADMIN_USER.email, ADMIN_USER.password);

    const result = await apiPost(page, `/companies/${companyId}/issues`, {
      title: "Admin Test Issue",
      body: "Created by admin role",
    });
    expect([200, 201]).toContain(result.status);
  });

  test("12. Admin: cannot create company", async ({ page }) => {
    await signIn(page, ADMIN_USER.email, ADMIN_USER.password);

    const result = await apiPost(page, "/companies", {
      name: "Admin Company",
    });
    // Should be 403 (instance admin required)
    expect(result.status).toBe(403);
  });

  test("13. Admin: User Management page visible with Users sidebar link", async ({ page }) => {
    await signIn(page, ADMIN_USER.email, ADMIN_USER.password);
    await page.goto(`${BASE}/PAP/company/settings/users`);

    await expect(page.getByRole("heading", { name: "User Management" })).toBeVisible();
    // Admin should see Create User button
    await expect(page.getByRole("button", { name: "Create User" })).toBeVisible();
  });

  // -------------------------------------------------------------------------
  // Normal User login & permission checks
  // -------------------------------------------------------------------------

  test("14. User: login and verify role", async ({ page }) => {
    await signIn(page, NORMAL_USER.email, NORMAL_USER.password);

    const me = await apiGet(page, "/users/me");
    expect(me.status).toBe(200);
    expect(me.body.role).toBe("user");
  });

  test("15. User: can read users list", async ({ page }) => {
    await signIn(page, NORMAL_USER.email, NORMAL_USER.password);

    const result = await apiGet(page, "/users");
    expect(result.status).toBe(200);
  });

  test("16. User: cannot create users", async ({ page }) => {
    await signIn(page, NORMAL_USER.email, NORMAL_USER.password);

    const result = await apiPost(page, "/users", {
      name: "User-Created",
      email: "user-created@rbac.test",
      password: "Test1234!",
      role: "guest",
    });
    expect(result.status).toBe(403);
  });

  test("17. User: cannot delete users", async ({ page }) => {
    await signIn(page, NORMAL_USER.email, NORMAL_USER.password);

    // Get a user ID to try to delete
    const users = await apiGet(page, "/users");
    const guest = users.body.find((u: any) => u.role === "guest");
    if (guest) {
      const result = await apiDelete(page, `/users/${guest.id}`);
      expect(result.status).toBe(403);
    }
  });

  test("18. User: cannot assign roles", async ({ page }) => {
    await signIn(page, NORMAL_USER.email, NORMAL_USER.password);

    const users = await apiGet(page, "/users");
    const guest = users.body.find((u: any) => u.role === "guest");
    if (guest) {
      const result = await apiPatch(page, `/users/${guest.id}/role`, { role: "user" });
      expect(result.status).toBe(403);
    }
  });

  test("19. User: can create agent", async ({ page }) => {
    await signIn(page, NORMAL_USER.email, NORMAL_USER.password);

    const result = await apiPost(page, `/companies/${companyId}/agents`, {
      name: "User Test Agent",
      adapter: "claude-local",
    });
    expect([200, 201]).toContain(result.status);
  });

  test("20. User: can create issue", async ({ page }) => {
    await signIn(page, NORMAL_USER.email, NORMAL_USER.password);

    const result = await apiPost(page, `/companies/${companyId}/issues`, {
      title: "User Test Issue",
      body: "Created by user role",
    });
    expect([200, 201]).toContain(result.status);
  });

  test("21. User: cannot create company", async ({ page }) => {
    await signIn(page, NORMAL_USER.email, NORMAL_USER.password);

    const result = await apiPost(page, "/companies", {
      name: "User Company",
    });
    expect(result.status).toBe(403);
  });

  test("22. User: User Management page - no Create User button", async ({ page }) => {
    await signIn(page, NORMAL_USER.email, NORMAL_USER.password);
    await page.goto(`${BASE}/PAP/company/settings/users`);

    // User can see the page (has users:read)
    await expect(page.getByRole("heading", { name: "User Management" })).toBeVisible();
    // But should NOT see Create User button (no users:create)
    await expect(page.getByRole("button", { name: "Create User" })).not.toBeVisible();
  });

  // -------------------------------------------------------------------------
  // Guest login & permission checks
  // -------------------------------------------------------------------------

  test("23. Guest: login and verify role", async ({ page }) => {
    await signIn(page, GUEST_USER.email, GUEST_USER.password);

    const me = await apiGet(page, "/users/me");
    expect(me.status).toBe(200);
    expect(me.body.role).toBe("guest");
  });

  test("24. Guest: can read users list (read-only)", async ({ page }) => {
    await signIn(page, GUEST_USER.email, GUEST_USER.password);

    const result = await apiGet(page, "/users");
    expect(result.status).toBe(200);
  });

  test("25. Guest: cannot create users", async ({ page }) => {
    await signIn(page, GUEST_USER.email, GUEST_USER.password);

    const result = await apiPost(page, "/users", {
      name: "Guest-Created",
      email: "guest-created@rbac.test",
      password: "Test1234!",
      role: "guest",
    });
    expect(result.status).toBe(403);
  });

  test("26. Guest: cannot create agent", async ({ page }) => {
    await signIn(page, GUEST_USER.email, GUEST_USER.password);

    const result = await apiPost(page, `/companies/${companyId}/agents`, {
      name: "Guest Test Agent",
      adapter: "claude-local",
    });
    expect(result.status).toBe(403);
  });

  test("27. Guest: cannot create issue", async ({ page }) => {
    await signIn(page, GUEST_USER.email, GUEST_USER.password);

    const result = await apiPost(page, `/companies/${companyId}/issues`, {
      title: "Guest Test Issue",
      body: "Should not be created",
    });
    expect(result.status).toBe(403);
  });

  test("28. Guest: can read agents (read-only)", async ({ page }) => {
    await signIn(page, GUEST_USER.email, GUEST_USER.password);

    const result = await apiGet(page, `/companies/${companyId}/agents`);
    expect(result.status).toBe(200);
    expect(result.body.length).toBeGreaterThan(0);
  });

  test("29. Guest: can read issues (read-only)", async ({ page }) => {
    await signIn(page, GUEST_USER.email, GUEST_USER.password);

    const result = await apiGet(page, `/companies/${companyId}/issues`);
    expect(result.status).toBe(200);
  });

  test("30. Guest: cannot delete users", async ({ page }) => {
    await signIn(page, GUEST_USER.email, GUEST_USER.password);

    const users = await apiGet(page, "/users");
    const normalUser = users.body.find((u: any) => u.email === NORMAL_USER.email);
    if (normalUser) {
      const result = await apiDelete(page, `/users/${normalUser.id}`);
      expect(result.status).toBe(403);
    }
  });

  test("31. Guest: sidebar should NOT show Users link", async ({ page }) => {
    await signIn(page, GUEST_USER.email, GUEST_USER.password);
    await page.goto(`${BASE}/PAP/dashboard`);

    // Wait for sidebar to load
    await expect(page.getByText("Dashboard")).toBeVisible();
    // Users link should not be visible for guest
    const usersLink = page.locator('nav a', { hasText: "Users" });
    await expect(usersLink).not.toBeVisible();
  });

  // -------------------------------------------------------------------------
  // Profile page tests
  // -------------------------------------------------------------------------

  test("32. All roles: profile page shows correct role", async ({ page }) => {
    // Test superadmin profile
    await signIn(page, SUPERADMIN.email, SUPERADMIN.password);
    await page.goto(`${BASE}/PAP/profile`);
    await expect(page.getByText("Super Admin")).toBeVisible();

    await signOut(page);

    // Test guest profile
    await signIn(page, GUEST_USER.email, GUEST_USER.password);
    await page.goto(`${BASE}/PAP/profile`);
    await expect(page.getByText("Guest")).toBeVisible();
  });

  test("33. Profile: user can update own name", async ({ page }) => {
    await signIn(page, NORMAL_USER.email, NORMAL_USER.password);

    const result = await apiPatch(page, "/users/me", { name: "Updated Normal User" });
    expect(result.status).toBe(200);
    expect(result.body.name).toBe("Updated Normal User");

    // Revert
    await apiPatch(page, "/users/me", { name: NORMAL_USER.name });
  });

  // -------------------------------------------------------------------------
  // Role change & cascading permission tests
  // -------------------------------------------------------------------------

  test("34. Superadmin: change user role from user to guest", async ({ page }) => {
    await signIn(page, SUPERADMIN.email, SUPERADMIN.password);

    const users = await apiGet(page, "/users");
    const normalUser = users.body.find((u: any) => u.email === NORMAL_USER.email);

    const result = await apiPatch(page, `/users/${normalUser.id}/role`, { role: "guest" });
    expect(result.status).toBe(200);
    expect(result.body.role).toBe("guest");

    // Revert back to user
    await apiPatch(page, `/users/${normalUser.id}/role`, { role: "user" });
  });

  test("35. Admin: cannot change role to admin or superadmin", async ({ page }) => {
    await signIn(page, ADMIN_USER.email, ADMIN_USER.password);

    const users = await apiGet(page, "/users");
    const guest = users.body.find((u: any) => u.email === GUEST_USER.email);

    // Admin cannot promote to admin
    const adminResult = await apiPatch(page, `/users/${guest.id}/role`, { role: "admin" });
    expect(adminResult.status).toBe(403);

    // Admin cannot promote to superadmin
    const superResult = await apiPatch(page, `/users/${guest.id}/role`, { role: "superadmin" });
    expect(superResult.status).toBe(403);

    // Admin CAN change to user (allowed)
    const userResult = await apiPatch(page, `/users/${guest.id}/role`, { role: "user" });
    expect(userResult.status).toBe(200);

    // Revert
    await signOut(page);
    await signIn(page, SUPERADMIN.email, SUPERADMIN.password);
    await apiPatch(page, `/users/${guest.id}/role`, { role: "guest" });
  });

  // -------------------------------------------------------------------------
  // Delete user tests
  // -------------------------------------------------------------------------

  test("36. Superadmin: can delete non-superadmin user", async ({ page }) => {
    await signIn(page, SUPERADMIN.email, SUPERADMIN.password);

    // Create a temp user to delete
    const temp = await apiPost(page, "/users", {
      name: "Temp Delete",
      email: "temp-delete@rbac.test",
      password: "Test1234!",
      role: "guest",
    });
    expect(temp.status).toBe(201);

    const deleteResult = await apiDelete(page, `/users/${temp.body.id}`);
    expect(deleteResult.status).toBe(204);

    // Verify deleted
    const getResult = await apiGet(page, `/users/${temp.body.id}`);
    expect(getResult.status).toBe(404);
  });

  test("37. Superadmin: cannot delete superadmin user", async ({ page }) => {
    await signIn(page, SUPERADMIN.email, SUPERADMIN.password);

    const me = await apiGet(page, "/users/me");
    const result = await apiDelete(page, `/users/${me.body.id}`);
    expect(result.status).toBe(400); // badRequest: Cannot delete superadmin
  });

  // -------------------------------------------------------------------------
  // Company membership tests
  // -------------------------------------------------------------------------

  test("38. Superadmin: add/remove user from company", async ({ page }) => {
    await signIn(page, SUPERADMIN.email, SUPERADMIN.password);

    // Create a second company
    const newCompany = await apiPost(page, "/companies", { name: "Second Company" });
    expect(newCompany.status).toBe(201);
    const newCompanyId = newCompany.body.id;

    // Get guest user ID
    const users = await apiGet(page, "/users");
    const guest = users.body.find((u: any) => u.email === GUEST_USER.email);

    // Add guest to second company
    const addResult = await apiPost(page, `/users/${guest.id}/companies`, { companyId: newCompanyId });
    expect(addResult.status).toBe(200);
    expect(addResult.body.companies.length).toBeGreaterThanOrEqual(2);

    // Remove guest from second company
    const removeResult = await apiDelete(page, `/users/${guest.id}/companies/${newCompanyId}`);
    expect(removeResult.status).toBe(204);
  });

  // -------------------------------------------------------------------------
  // Database verification
  // -------------------------------------------------------------------------

  test("39. DB: verify all users have correct roles via API", async ({ page }) => {
    await signIn(page, SUPERADMIN.email, SUPERADMIN.password);

    const users = await apiGet(page, "/users");
    expect(users.status).toBe(200);

    const userMap = new Map(users.body.map((u: any) => [u.email, u]));

    expect(userMap.get(SUPERADMIN.email)?.role).toBe("superadmin");
    expect(userMap.get(ADMIN_USER.email)?.role).toBe("admin");
    expect(userMap.get(NORMAL_USER.email)?.role).toBe("user");
    expect(userMap.get(GUEST_USER.email)?.role).toBe("guest");
  });

  // -------------------------------------------------------------------------
  // Unauthenticated access
  // -------------------------------------------------------------------------

  test("40. Unauthenticated: all user APIs return 401", async ({ page }) => {
    // Don't sign in — test without auth
    await page.goto(`${BASE}/auth`);
    await signOut(page);

    const endpoints = [
      () => apiGet(page, "/users/me"),
      () => apiGet(page, "/users"),
      () => apiPost(page, "/users", { name: "x", email: "x@x.com", password: "x" }),
    ];

    for (const fn of endpoints) {
      const result = await fn();
      expect([401, 403]).toContain(result.status);
    }
  });
});

import { test, expect, type Page } from "@playwright/test";

const BASE = "http://127.0.0.1:3100";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

async function signUpViaApi(page: Page, name: string, email: string, password: string) {
  // Use better-auth's sign-up API directly (more reliable than UI)
  const res = await page.request.post(`${BASE}/api/auth/sign-up/email`, {
    data: { name, email, password },
  });
  // 200 = success, 422 = email already exists (idempotent)
  if (res.status() !== 200 && res.status() !== 422) {
    throw new Error(`Sign-up failed: ${res.status()} ${await res.text()}`);
  }
  // Now sign in to get session cookie
  await signIn(page, email, password);
}

async function signIn(page: Page, email: string, password: string) {
  await page.goto(`${BASE}/auth`);
  await page.locator('input[type="email"]').fill(email);
  await page.locator('input[type="password"]').fill(password);
  await page.getByRole("button", { name: "Sign In" }).click();
  await expect(page).not.toHaveURL(/\/auth/, { timeout: 15000 });
}

async function signOut(page: Page) {
  // Clear session via API
  await page.evaluate(() => fetch("/api/auth/sign-out", { method: "POST", credentials: "include" }));
}

async function apiGet(page: Page, path: string) {
  const res = await page.request.get(`${BASE}/api${path}`);
  return { status: res.status(), body: await res.json().catch(() => null) };
}

async function apiPost(page: Page, path: string, body: Record<string, unknown>) {
  const res = await page.request.post(`${BASE}/api${path}`, { data: body });
  return { status: res.status(), body: await res.json().catch(() => null) };
}

async function apiPatch(page: Page, path: string, body: Record<string, unknown>) {
  const res = await page.request.patch(`${BASE}/api${path}`, { data: body });
  return { status: res.status(), body: await res.json().catch(() => null) };
}

async function apiDelete(page: Page, path: string) {
  const res = await page.request.delete(`${BASE}/api${path}`);
  return { status: res.status(), body: await res.text().catch(() => null) };
}

// ---------------------------------------------------------------------------
// Test Data
// ---------------------------------------------------------------------------

const SUPERADMIN = { name: "Super Admin", email: "superadmin@rbac.test", password: "Super1234!" };
const ADMIN_USER = { name: "Admin User", email: "admin@rbac.test", password: "Admin1234!" };
