    expect(emails).toContain(NORMAL_USER.email);
    expect(emails).toContain(GUEST_USER.email);
  });

  test("3. Superadmin: can create company", async ({ request }) => {
    await signInApi(request, SUPERADMIN.email, SUPERADMIN.password);
