    expect(result.status).toBe(201);
  });

  test("4. Superadmin: can create agent", async ({ request }) => {
    await signInApi(request, SUPERADMIN.email, SUPERADMIN.password);
    const result = await apiPost(request, `/companies/${companyId}/agents`, {
