    // Users link should not be visible for guest
    const usersLink = page.locator('nav a', { hasText: "Users" });
    await expect(usersLink).not.toBeVisible();
  });

  // -------------------------------------------------------------------------
  // Profile page tests
  // -------------------------------------------------------------------------

  test("32. All roles: profile page shows correct role", async ({ page }) => {
    // Test superadmin profile
    await signIn(page, SUPERADMIN.email, SUPERADMIN.password);
    await page.goto(`${BASE}/PAP/profile`);
    await expect(page.getByText("Super Admin")).toBeVisible();

    await signOut(page);

    // Test guest profile
    await signIn(page, GUEST_USER.email, GUEST_USER.password);
    await page.goto(`${BASE}/PAP/profile`);
    await expect(page.getByText("Guest")).toBeVisible();
  });

  test("33. Profile: user can update own name", async ({ page }) => {
    await signIn(page, NORMAL_USER.email, NORMAL_USER.password);

    const result = await apiPatch(page, "/users/me", { name: "Updated Normal User" });
    expect(result.status).toBe(200);
    expect(result.body.name).toBe("Updated Normal User");

    // Revert
    await apiPatch(page, "/users/me", { name: NORMAL_USER.name });
  });

  // -------------------------------------------------------------------------
  // Role change & cascading permission tests
  // -------------------------------------------------------------------------

  test("34. Superadmin: change user role from user to guest", async ({ page }) => {
    await signIn(page, SUPERADMIN.email, SUPERADMIN.password);

    const users = await apiGet(page, "/users");
    const normalUser = users.body.find((u: any) => u.email === NORMAL_USER.email);

    const result = await apiPatch(page, `/users/${normalUser.id}/role`, { role: "guest" });
    expect(result.status).toBe(200);
    expect(result.body.role).toBe("guest");

    // Revert back to user
    await apiPatch(page, `/users/${normalUser.id}/role`, { role: "user" });
  });

  test("35. Admin: cannot change role to admin or superadmin", async ({ page }) => {
    await signIn(page, ADMIN_USER.email, ADMIN_USER.password);

    const users = await apiGet(page, "/users");
    const guest = users.body.find((u: any) => u.email === GUEST_USER.email);

    // Admin cannot promote to admin
    const adminResult = await apiPatch(page, `/users/${guest.id}/role`, { role: "admin" });
    expect(adminResult.status).toBe(403);

    // Admin cannot promote to superadmin
    const superResult = await apiPatch(page, `/users/${guest.id}/role`, { role: "superadmin" });
    expect(superResult.status).toBe(403);

    // Admin CAN change to user (allowed)
    const userResult = await apiPatch(page, `/users/${guest.id}/role`, { role: "user" });
    expect(userResult.status).toBe(200);

    // Revert
    await signOut(page);
    await signIn(page, SUPERADMIN.email, SUPERADMIN.password);
    await apiPatch(page, `/users/${guest.id}/role`, { role: "guest" });
  });

  // -------------------------------------------------------------------------
  // Delete user tests
  // -------------------------------------------------------------------------

  test("36. Superadmin: can delete non-superadmin user", async ({ page }) => {
    await signIn(page, SUPERADMIN.email, SUPERADMIN.password);

    // Create a temp user to delete
    const temp = await apiPost(page, "/users", {
      name: "Temp Delete",
      email: "temp-delete@rbac.test",
      password: "Test1234!",
      role: "guest",
    });
    expect(temp.status).toBe(201);

    const deleteResult = await apiDelete(page, `/users/${temp.body.id}`);
    expect(deleteResult.status).toBe(204);

    // Verify deleted
    const getResult = await apiGet(page, `/users/${temp.body.id}`);
    expect(getResult.status).toBe(404);
  });

  test("37. Superadmin: cannot delete superadmin user", async ({ page }) => {
    await signIn(page, SUPERADMIN.email, SUPERADMIN.password);

    const me = await apiGet(page, "/users/me");
    const result = await apiDelete(page, `/users/${me.body.id}`);
    expect(result.status).toBe(400); // badRequest: Cannot delete superadmin
  });

  // -------------------------------------------------------------------------
  // Company membership tests
  // -------------------------------------------------------------------------

  test("38. Superadmin: add/remove user from company", async ({ page }) => {
    await signIn(page, SUPERADMIN.email, SUPERADMIN.password);

    // Create a second company
    const newCompany = await apiPost(page, "/companies", { name: "Second Company" });
    expect(newCompany.status).toBe(201);
    const newCompanyId = newCompany.body.id;

    // Get guest user ID
    const users = await apiGet(page, "/users");
    const guest = users.body.find((u: any) => u.email === GUEST_USER.email);

    // Add guest to second company
    const addResult = await apiPost(page, `/users/${guest.id}/companies`, { companyId: newCompanyId });
    expect(addResult.status).toBe(200);
    expect(addResult.body.companies.length).toBeGreaterThanOrEqual(2);

    // Remove guest from second company
    const removeResult = await apiDelete(page, `/users/${guest.id}/companies/${newCompanyId}`);
    expect(removeResult.status).toBe(204);
  });

  // -------------------------------------------------------------------------
  // Database verification
  // -------------------------------------------------------------------------

  test("39. DB: verify all users have correct roles via API", async ({ page }) => {
    await signIn(page, SUPERADMIN.email, SUPERADMIN.password);

    const users = await apiGet(page, "/users");
    expect(users.status).toBe(200);

    const userMap = new Map(users.body.map((u: any) => [u.email, u]));

    expect(userMap.get(SUPERADMIN.email)?.role).toBe("superadmin");
    expect(userMap.get(ADMIN_USER.email)?.role).toBe("admin");
    expect(userMap.get(NORMAL_USER.email)?.role).toBe("user");
    expect(userMap.get(GUEST_USER.email)?.role).toBe("guest");
  });

  // -------------------------------------------------------------------------
  // Unauthenticated access
  // -------------------------------------------------------------------------

  test("40. Unauthenticated: all user APIs return 401", async ({ page }) => {
    // Don't sign in — test without auth
    await page.goto(`${BASE}/auth`);
    await signOut(page);

    const endpoints = [
      () => apiGet(page, "/users/me"),
      () => apiGet(page, "/users"),
      () => apiPost(page, "/users", { name: "x", email: "x@x.com", password: "x" }),
    ];

    for (const fn of endpoints) {
      const result = await fn();
      expect([401, 403]).toContain(result.status);
    }
  });
});

