    const temp = await apiPost(request, "/users", {
      name: "Temp User",
      email: `temp-${Date.now()}@test.local`,
      password: "Temp1234!",
      role: "guest",
    });
    expect(temp.status).toBe(201);

    const del = await apiDelete(request, `/users/${temp.body.id}`);
    expect(del.status).toBe(204);

