 62→export async function createApp(
 63→  db: Db,
 64→  opts: {
 65→    uiMode: UiMode;
 66→    serverPort: number;
 67→    storageService: StorageService;
 68→    deploymentMode: DeploymentMode;
 69→    deploymentExposure: DeploymentExposure;
 70→    allowedHostnames: string[];
 71→    bindHost: string;
 72→    authReady: boolean;
 73→    companyDeletionEnabled: boolean;
 74→    instanceId?: string;
 75→    hostVersion?: string;
 76→    localPluginDir?: string;
 77→    betterAuthHandler?: express.RequestHandler;
 78→    resolveSession?: (req: ExpressRequest) => Promise<BetterAuthSessionResult | null>;
 79→  },
 80→) {
 81→  const app = express();
 82→
 83→  app.use(express.json({
 84→    // Company import/export payloads can inline full portable packages.
 85→    limit: "10mb",
 86→    verify: (req, _res, buf) => {
 87→      (req as unknown as { rawBody: Buffer }).rawBody = buf;
 88→    },
 89→  }));
 90→  app.use(httpLogger);
 91→  const privateHostnameGateEnabled =
 92→    opts.deploymentMode === "authenticated" && opts.deploymentExposure === "private";
 93→  const privateHostnameAllowSet = resolvePrivateHostnameAllowSet({
 94→    allowedHostnames: opts.allowedHostnames,
 95→    bindHost: opts.bindHost,
 96→  });
 97→  app.use(
 98→    privateHostnameGuard({
 99→      enabled: privateHostnameGateEnabled,
100→      allowedHostnames: opts.allowedHostnames,
101→      bindHost: opts.bindHost,
102→    }),
103→  );
104→  app.use(
105→    actorMiddleware(db, {
106→      deploymentMode: opts.deploymentMode,
107→      resolveSession: opts.resolveSession,
108→    }),
109→  );
110→  app.get("/api/auth/get-session", (req, res) => {
111→    if (req.actor.type !== "board" || !req.actor.userId) {
112→      res.status(401).json({ error: "Unauthorized" });
113→      return;
114→    }
115→    res.json({
116→      session: {
117→        id: `paperclip:${req.actor.source}:${req.actor.userId}`,
118→        userId: req.actor.userId,
119→      },
120→      user: {
121→        id: req.actor.userId,
122→        email: null,
123→        name: req.actor.source === "local_implicit" ? "Local Board" : null,
124→      },
125→    });
126→  });
127→  if (opts.betterAuthHandler) {
128→    app.all("/api/auth/*authPath", opts.betterAuthHandler);
129→  }
130→  app.use(llmRoutes(db));
131→
132→  // Mount API routes
133→  const api = Router();
134→  api.use(boardMutationGuard());
135→  api.use(
136→    "/health",
137→    healthRoutes(db, {
138→      deploymentMode: opts.deploymentMode,
139→      deploymentExposure: opts.deploymentExposure,
140→      authReady: opts.authReady,
141→      companyDeletionEnabled: opts.companyDeletionEnabled,
142→    }),
143→  );
144→  api.use("/companies", companyRoutes(db, opts.storageService));
145→  api.use(companySkillRoutes(db));
146→  api.use(agentRoutes(db));
147→  api.use(assetRoutes(db, opts.storageService));
148→  api.use(projectRoutes(db));
149→  api.use(issueRoutes(db, opts.storageService));
150→  api.use(routineRoutes(db));
151→  api.use(executionWorkspaceRoutes(db));
152→  api.use(goalRoutes(db));
153→  api.use(approvalRoutes(db));
154→  api.use(secretRoutes(db));
155→  api.use(costRoutes(db));
156→  api.use(activityRoutes(db));
157→  api.use(dashboardRoutes(db));
158→  api.use(sidebarBadgeRoutes(db));
159→  api.use(instanceSettingsRoutes(db));
160→  api.use(userRoutes(db, { hashPassword }));
161→  const hostServicesDisposers = new Map<string, () => void>();
162→  const workerManager = createPluginWorkerManager();
163→  const pluginRegistry = pluginRegistryService(db);
164→  const eventBus = createPluginEventBus();
165→  setPluginEventBus(eventBus);
166→  const jobStore = pluginJobStore(db);
167→  const lifecycle = pluginLifecycleManager(db, { workerManager });
168→  const scheduler = createPluginJobScheduler({
169→    db,
170→    jobStore,
171→    workerManager,
172→  });
173→  const toolDispatcher = createPluginToolDispatcher({
174→    workerManager,
175→    lifecycleManager: lifecycle,
176→    db,
177→  });
178→  const jobCoordinator = createPluginJobCoordinator({
179→    db,
180→    lifecycle,
181→    scheduler,
182→    jobStore,
183→  });
184→  const hostServiceCleanup = createPluginHostServiceCleanup(lifecycle, hostServicesDisposers);
185→  const loader = pluginLoader(
186→    db,
187→    { localPluginDir: opts.localPluginDir ?? DEFAULT_LOCAL_PLUGIN_DIR },
188→    {
189→      workerManager,
190→      eventBus,
191→      jobScheduler: scheduler,
192→      jobStore,
193→      toolDispatcher,
194→      lifecycleManager: lifecycle,
195→      instanceInfo: {
196→        instanceId: opts.instanceId ?? "default",
197→        hostVersion: opts.hostVersion ?? "0.0.0",
198→      },
199→      buildHostHandlers: (pluginId, manifest) => {
200→        const notifyWorker = (method: string, params: unknown) => {
201→          const handle = workerManager.getWorker(pluginId);
202→          if (handle) handle.notify(method, params);
203→        };
204→        const services = buildHostServices(db, pluginId, manifest.id, eventBus, notifyWorker);
205→        hostServicesDisposers.set(pluginId, () => services.dispose());
206→        return createHostClientHandlers({
207→          pluginId,
208→          capabilities: manifest.capabilities,
209→          services,
210→        });
211→      },
212→    },
213→  );
214→  api.use(
215→    pluginRoutes(
216→      db,
217→      loader,
218→      { scheduler, jobStore },
219→      { workerManager },
220→      { toolDispatcher },
221→      { workerManager },
222→    ),
223→  );
224→  api.use(
225→    accessRoutes(db, {
226→      deploymentMode: opts.deploymentMode,
227→      deploymentExposure: opts.deploymentExposure,
228→      bindHost: opts.bindHost,
229→      allowedHostnames: opts.allowedHostnames,
230→    }),
231→  );
232→  app.use("/api", api);
233→  app.use("/api", (_req, res) => {
234→    res.status(404).json({ error: "API route not found" });
235→  });
236→  app.use(pluginUiStaticRoutes(db, {
237→    localPluginDir: opts.localPluginDir ?? DEFAULT_LOCAL_PLUGIN_DIR,
238→  }));
239→
240→  const __dirname = path.dirname(fileURLToPath(import.meta.url));
241→  if (opts.uiMode === "static") {
242→    // Try published location first (server/ui-dist/), then monorepo dev location (../../ui/dist)
243→    const candidates = [
244→      path.resolve(__dirname, "../ui-dist"),
245→      path.resolve(__dirname, "../../ui/dist"),
246→    ];
247→    const uiDist = candidates.find((p) => fs.existsSync(path.join(p, "index.html")));
248→    if (uiDist) {
249→      const indexHtml = applyUiBranding(fs.readFileSync(path.join(uiDist, "index.html"), "utf-8"));
250→      app.use(express.static(uiDist));
251→      app.get(/.*/, (_req, res) => {
252→        res.status(200).set("Content-Type", "text/html").end(indexHtml);
253→      });
254→    } else {
255→      console.warn("[paperclip] UI dist not found; running in API-only mode");
256→    }
257→  }
258→
259→  if (opts.uiMode === "vite-dev") {
260→    const uiRoot = path.resolve(__dirname, "../../ui");
261→    const hmrPort = resolveViteHmrPort(opts.serverPort);
262→    const { createServer: createViteServer } = await import("vite");
263→    const vite = await createViteServer({
264→      root: uiRoot,
265→      appType: "custom",
266→      server: {
267→        middlewareMode: true,
268→        hmr: {
269→          host: opts.bindHost,
270→          port: hmrPort,
271→          clientPort: hmrPort,
272→        },
273→        allowedHosts: privateHostnameGateEnabled ? Array.from(privateHostnameAllowSet) : undefined,
274→      },
275→    });
276→
277→    app.use(vite.middlewares);
278→    app.get(/.*/, async (req, res, next) => {
279→      try {
280→        const templatePath = path.resolve(uiRoot, "index.html");
281→        const template = fs.readFileSync(templatePath, "utf-8");
282→        const html = applyUiBranding(await vite.transformIndexHtml(req.originalUrl, template));
283→        res.status(200).set({ "Content-Type": "text/html" }).end(html);
284→      } catch (err) {
285→        next(err);
286→      }
287→    });
288→  }
289→
290→  app.use(errorHandler);
291→
292→  jobCoordinator.start();
293→  scheduler.start();
294→  void toolDispatcher.initialize().catch((err) => {
295→    logger.error({ err }, "Failed to initialize plugin tool dispatcher");
296→  });
297→  const devWatcher = opts.uiMode === "vite-dev"
298→    ? createPluginDevWatcher(
299→      lifecycle,
300→      async (pluginId) => (await pluginRegistry.getById(pluginId))?.packagePath ?? null,
301→    )
302→    : null;
303→  void loader.loadAll().then((result) => {
304→    if (!result) return;
305→    for (const loaded of result.results) {
306→      if (devWatcher && loaded.success && loaded.plugin.packagePath) {
307→        devWatcher.watch(loaded.plugin.id, loaded.plugin.packagePath);
308→      }
309→    }
310→  }).catch((err) => {
311→    logger.error({ err }, "Failed to load ready plugins on startup");
312→  });
313→  process.once("exit", () => {
314→    devWatcher?.close();
315→    hostServiceCleanup.disposeAll();
316→    hostServiceCleanup.teardown();
317→  });
318→  process.once("beforeExit", () => {
319→    void flushPluginLogBuffer();
320→  });
321→
322→  return app;
323→}
