 72→export async function startServer(): Promise<StartedServer> {
 73→  const config = loadConfig();
 74→  if (process.env.PAPERCLIP_SECRETS_PROVIDER === undefined) {
 75→    process.env.PAPERCLIP_SECRETS_PROVIDER = config.secretsProvider;
 76→  }
 77→  if (process.env.PAPERCLIP_SECRETS_STRICT_MODE === undefined) {
 78→    process.env.PAPERCLIP_SECRETS_STRICT_MODE = config.secretsStrictMode ? "true" : "false";
 79→  }
 80→  if (process.env.PAPERCLIP_SECRETS_MASTER_KEY_FILE === undefined) {
 81→    process.env.PAPERCLIP_SECRETS_MASTER_KEY_FILE = config.secretsMasterKeyFilePath;
 82→  }
 83→  
 84→  type MigrationSummary =
 85→    | "skipped"
 86→    | "already applied"
 87→    | "applied (empty database)"
 88→    | "applied (pending migrations)";
 89→  
 90→  function formatPendingMigrationSummary(migrations: string[]): string {
 91→    if (migrations.length === 0) return "none";
 92→    return migrations.length > 3
 93→      ? `${migrations.slice(0, 3).join(", ")} (+${migrations.length - 3} more)`
 94→      : migrations.join(", ");
 95→  }
 96→  
 97→  async function promptApplyMigrations(migrations: string[]): Promise<boolean> {
 98→    if (process.env.PAPERCLIP_MIGRATION_PROMPT === "never") return false;
 99→    if (process.env.PAPERCLIP_MIGRATION_AUTO_APPLY === "true") return true;
100→    if (!stdin.isTTY || !stdout.isTTY) return true;
101→  
102→    const prompt = createInterface({ input: stdin, output: stdout });
103→    try {
104→      const answer = (await prompt.question(
105→        `Apply pending migrations (${formatPendingMigrationSummary(migrations)}) now? (y/N): `,
106→      )).trim().toLowerCase();
107→      return answer === "y" || answer === "yes";
108→    } finally {
109→      prompt.close();
110→    }
111→  }
112→  
113→  type EnsureMigrationsOptions = {
114→    autoApply?: boolean;
115→  };
116→  
117→  async function ensureMigrations(
118→    connectionString: string,
119→    label: string,
120→    opts?: EnsureMigrationsOptions,
121→  ): Promise<MigrationSummary> {
122→    const autoApply = opts?.autoApply === true;
123→    let state = await inspectMigrations(connectionString);
124→    if (state.status === "needsMigrations" && state.reason === "pending-migrations") {
125→      const repair = await reconcilePendingMigrationHistory(connectionString);
126→      if (repair.repairedMigrations.length > 0) {
127→        logger.warn(
128→          { repairedMigrations: repair.repairedMigrations },
129→          `${label} had drifted migration history; repaired migration journal entries from existing schema state.`,
130→        );
131→        state = await inspectMigrations(connectionString);
132→        if (state.status === "upToDate") return "already applied";
133→      }
134→    }
135→    if (state.status === "upToDate") return "already applied";
136→    if (state.status === "needsMigrations" && state.reason === "no-migration-journal-non-empty-db") {
137→      logger.warn(
138→        { tableCount: state.tableCount },
139→        `${label} has existing tables but no migration journal. Run migrations manually to sync schema.`,
140→      );
141→      const apply = autoApply ? true : await promptApplyMigrations(state.pendingMigrations);
142→      if (!apply) {
143→        throw new Error(
144→          `${label} has pending migrations (${formatPendingMigrationSummary(state.pendingMigrations)}). ` +
145→            "Refusing to start against a stale schema. Run pnpm db:migrate or set PAPERCLIP_MIGRATION_AUTO_APPLY=true.",
146→        );
147→      }
148→  
149→      logger.info({ pendingMigrations: state.pendingMigrations }, `Applying ${state.pendingMigrations.length} pending migrations for ${label}`);
150→      await applyPendingMigrations(connectionString);
151→      return "applied (pending migrations)";
152→    }
153→  
154→    const apply = autoApply ? true : await promptApplyMigrations(state.pendingMigrations);
155→    if (!apply) {
156→      throw new Error(
157→        `${label} has pending migrations (${formatPendingMigrationSummary(state.pendingMigrations)}). ` +
158→          "Refusing to start against a stale schema. Run pnpm db:migrate or set PAPERCLIP_MIGRATION_AUTO_APPLY=true.",
159→      );
160→    }
161→  
162→    logger.info({ pendingMigrations: state.pendingMigrations }, `Applying ${state.pendingMigrations.length} pending migrations for ${label}`);
163→    await applyPendingMigrations(connectionString);
164→    return "applied (pending migrations)";
165→  }
