247→  } else {
248→    const moduleName = "embedded-postgres";
249→    let EmbeddedPostgres: EmbeddedPostgresCtor;
250→    try {
251→      const mod = await import(moduleName);
252→      EmbeddedPostgres = mod.default as EmbeddedPostgresCtor;
253→    } catch {
254→      throw new Error(
255→        "Embedded PostgreSQL mode requires dependency `embedded-postgres`. Reinstall dependencies (without omitting required packages), or set DATABASE_URL for external Postgres.",
256→      );
257→    }
258→  
259→    const dataDir = resolve(config.embeddedPostgresDataDir);
260→    const configuredPort = config.embeddedPostgresPort;
261→    let port = configuredPort;
262→    const embeddedPostgresLogBuffer: string[] = [];
263→    const EMBEDDED_POSTGRES_LOG_BUFFER_LIMIT = 120;
264→    const verboseEmbeddedPostgresLogs = process.env.PAPERCLIP_EMBEDDED_POSTGRES_VERBOSE === "true";
265→    const appendEmbeddedPostgresLog = (message: unknown) => {
266→      const text = typeof message === "string" ? message : message instanceof Error ? message.message : String(message ?? "");
267→      for (const lineRaw of text.split(/\r?\n/)) {
268→        const line = lineRaw.trim();
269→        if (!line) continue;
270→        embeddedPostgresLogBuffer.push(line);
271→        if (embeddedPostgresLogBuffer.length > EMBEDDED_POSTGRES_LOG_BUFFER_LIMIT) {
272→          embeddedPostgresLogBuffer.splice(0, embeddedPostgresLogBuffer.length - EMBEDDED_POSTGRES_LOG_BUFFER_LIMIT);
273→        }
274→        if (verboseEmbeddedPostgresLogs) {
275→          logger.info({ embeddedPostgresLog: line }, "embedded-postgres");
276→        }
277→      }
278→    };
279→    const logEmbeddedPostgresFailure = (phase: "initialise" | "start", err: unknown) => {
280→      if (embeddedPostgresLogBuffer.length > 0) {
281→        logger.error(
282→          {
283→            phase,
284→            recentLogs: embeddedPostgresLogBuffer,
285→            err,
286→          },
287→          "Embedded PostgreSQL failed; showing buffered startup logs",
288→        );
289→      }
290→    };
291→  
292→    if (config.databaseMode === "postgres") {
293→      logger.warn("Database mode is postgres but no connection string was set; falling back to embedded PostgreSQL");
294→    }
295→  
296→    const clusterVersionFile = resolve(dataDir, "PG_VERSION");
297→    const clusterAlreadyInitialized = existsSync(clusterVersionFile);
298→    const postmasterPidFile = resolve(dataDir, "postmaster.pid");
299→    const isPidRunning = (pid: number): boolean => {
300→      try {
301→        process.kill(pid, 0);
302→        return true;
303→      } catch {
304→        return false;
305→      }
306→    };
307→  
308→    const getRunningPid = (): number | null => {
309→      if (!existsSync(postmasterPidFile)) return null;
310→      try {
311→        const pidLine = readFileSync(postmasterPidFile, "utf8").split("\n")[0]?.trim();
312→        const pid = Number(pidLine);
313→        if (!Number.isInteger(pid) || pid <= 0) return null;
314→        if (!isPidRunning(pid)) return null;
315→        return pid;
316→      } catch {
317→        return null;
318→      }
319→    };
320→  
321→    const runningPid = getRunningPid();
322→    if (runningPid) {
323→      logger.warn(`Embedded PostgreSQL already running; reusing existing process (pid=${runningPid}, port=${port})`);
324→    } else {
325→      const configuredAdminConnectionString = `postgres://paperclip:paperclip@127.0.0.1:${configuredPort}/postgres`;
326→      try {
327→        const actualDataDir = await getPostgresDataDirectory(configuredAdminConnectionString);
328→        if (
329→          typeof actualDataDir !== "string" ||
330→          resolve(actualDataDir) !== resolve(dataDir)
331→        ) {
332→          throw new Error("reachable postgres does not use the expected embedded data directory");
333→        }
334→        await ensurePostgresDatabase(configuredAdminConnectionString, "paperclip");
335→        logger.warn(
336→          `Embedded PostgreSQL appears to already be reachable without a pid file; reusing existing server on configured port ${configuredPort}`,
337→        );
338→      } catch {
339→        const detectedPort = await detectPort(configuredPort);
340→        if (detectedPort !== configuredPort) {
341→          logger.warn(`Embedded PostgreSQL port is in use; using next free port (requestedPort=${configuredPort}, selectedPort=${detectedPort})`);
342→        }
343→        port = detectedPort;
344→        logger.info(`Using embedded PostgreSQL because no DATABASE_URL set (dataDir=${dataDir}, port=${port})`);
345→        embeddedPostgres = new EmbeddedPostgres({
346→          databaseDir: dataDir,
347→          user: "paperclip",
348→          password: "paperclip",
349→          port,
350→          persistent: true,
351→          initdbFlags: ["--encoding=UTF8", "--locale=C"],
352→          onLog: appendEmbeddedPostgresLog,
353→          onError: appendEmbeddedPostgresLog,
354→        });
355→
356→        if (!clusterAlreadyInitialized) {
357→          try {
358→            await embeddedPostgres.initialise();
359→          } catch (err) {
360→            logEmbeddedPostgresFailure("initialise", err);
361→            throw err;
362→          }
363→        } else {
364→          logger.info(`Embedded PostgreSQL cluster already exists (${clusterVersionFile}); skipping init`);
365→        }
366→
367→        if (existsSync(postmasterPidFile)) {
368→          logger.warn("Removing stale embedded PostgreSQL lock file");
369→          rmSync(postmasterPidFile, { force: true });
370→        }
371→        try {
372→          await embeddedPostgres.start();
373→        } catch (err) {
374→          logEmbeddedPostgresFailure("start", err);
375→          throw err;
376→        }
377→        embeddedPostgresStartedByThisProcess = true;
378→      }
379→    }
380→  
381→    const embeddedAdminConnectionString = `postgres://paperclip:paperclip@127.0.0.1:${port}/postgres`;
382→    const dbStatus = await ensurePostgresDatabase(embeddedAdminConnectionString, "paperclip");
383→    if (dbStatus === "created") {
384→      logger.info("Created embedded PostgreSQL database: paperclip");
385→    }
386→  
387→    const embeddedConnectionString = `postgres://paperclip:paperclip@127.0.0.1:${port}/paperclip`;
388→    const shouldAutoApplyFirstRunMigrations = !clusterAlreadyInitialized || dbStatus === "created";
389→    if (shouldAutoApplyFirstRunMigrations) {
390→      logger.info("Detected first-run embedded PostgreSQL setup; applying pending migrations automatically");
391→    }
392→    migrationSummary = await ensureMigrations(embeddedConnectionString, "Embedded PostgreSQL", {
393→      autoApply: shouldAutoApplyFirstRunMigrations,
394→    });
395→  
396→    db = createDb(embeddedConnectionString);
397→    logger.info("Embedded PostgreSQL ready");
398→    activeDatabaseConnectionString = embeddedConnectionString;
399→    startupDbInfo = { mode: "embedded-postgres", dataDir, port };
400→  }
401→  
402→  if (config.deploymentMode === "local_trusted" && !isLoopbackHost(config.host)) {
403→    throw new Error(
404→      `local_trusted mode requires loopback host binding (received: ${config.host}). ` +
405→        "Use authenticated mode for non-loopback deployments.",
406→    );
407→  }
408→  
409→  if (config.deploymentMode === "local_trusted" && config.deploymentExposure !== "private") {
410→    throw new Error("local_trusted mode only supports private exposure");
411→  }
412→  
413→  if (config.deploymentMode === "authenticated") {
414→    if (config.authBaseUrlMode === "explicit" && !config.authPublicBaseUrl) {
415→      throw new Error("auth.baseUrlMode=explicit requires auth.publicBaseUrl");
416→    }
417→    if (config.deploymentExposure === "public") {
418→      if (config.authBaseUrlMode !== "explicit") {
419→        throw new Error("authenticated public exposure requires auth.baseUrlMode=explicit");
420→      }
421→      if (!config.authPublicBaseUrl) {
422→        throw new Error("authenticated public exposure requires auth.publicBaseUrl");
423→      }
424→    }
425→  }
426→  
427→  let authReady = config.deploymentMode === "local_trusted";
428→  let betterAuthHandler: RequestHandler | undefined;
429→  let resolveSession:
430→    | ((req: ExpressRequest) => Promise<BetterAuthSessionResult | null>)
431→    | undefined;
432→  let resolveSessionFromHeaders:
433→    | ((headers: Headers) => Promise<BetterAuthSessionResult | null>)
434→    | undefined;
435→  if (config.deploymentMode === "local_trusted") {
436→    await ensureLocalTrustedBoardPrincipal(db as any);
437→  }
438→  if (config.deploymentMode === "authenticated") {
439→    const {
440→      createBetterAuthHandler,
441→      createBetterAuthInstance,
442→      deriveAuthTrustedOrigins,
443→      resolveBetterAuthSession,
444→      resolveBetterAuthSessionFromHeaders,
445→    } = await import("./auth/better-auth.js");
446→    const betterAuthSecret =
447→      process.env.BETTER_AUTH_SECRET?.trim() ?? process.env.PAPERCLIP_AGENT_JWT_SECRET?.trim();
448→    if (!betterAuthSecret) {
449→      throw new Error(
450→        "authenticated mode requires BETTER_AUTH_SECRET (or PAPERCLIP_AGENT_JWT_SECRET) to be set",
451→      );
452→    }
453→    const derivedTrustedOrigins = deriveAuthTrustedOrigins(config);
454→    const envTrustedOrigins = (process.env.BETTER_AUTH_TRUSTED_ORIGINS ?? "")
455→      .split(",")
456→      .map((value) => value.trim())
457→      .filter((value) => value.length > 0);
458→    const effectiveTrustedOrigins = Array.from(new Set([...derivedTrustedOrigins, ...envTrustedOrigins]));
459→    logger.info(
460→      {
461→        authBaseUrlMode: config.authBaseUrlMode,
462→        authPublicBaseUrl: config.authPublicBaseUrl ?? null,
463→        trustedOrigins: effectiveTrustedOrigins,
464→        trustedOriginsSource: {
465→          derived: derivedTrustedOrigins.length,
466→          env: envTrustedOrigins.length,
467→        },
468→      },
469→      "Authenticated mode auth origin configuration",
470→    );
471→    const auth = createBetterAuthInstance(db as any, config, effectiveTrustedOrigins);
472→    betterAuthHandler = createBetterAuthHandler(auth);
473→    resolveSession = (req) => resolveBetterAuthSession(auth, req);
474→    resolveSessionFromHeaders = (headers) => resolveBetterAuthSessionFromHeaders(auth, headers);
475→    await initializeBoardClaimChallenge(db as any, { deploymentMode: config.deploymentMode });
476→    authReady = true;
477→
478→    // Auto-bootstrap: wrap resolveSession to bootstrap user on first login
479→    const bootstrap = bootstrapService(db as any);
480→    const originalResolveSession = resolveSession!;
481→    resolveSession = async (req) => {
482→      const session = await originalResolveSession(req);
483→      if (session?.user?.id) {
484→        try {
485→          await bootstrap.maybeBootstrapUser(
486→            session.user.id,
487→            session.user.name,
488→          );
489→        } catch (err) {
490→          logger.warn({ err, userId: session.user.id }, "Bootstrap check failed (non-fatal)");
491→        }
492→      }
493→      return session;
494→    };
495→  }
496→  
497→  const listenPort = await detectPort(config.port);
498→  const uiMode = config.uiDevMiddleware ? "vite-dev" : config.serveUi ? "static" : "none";
499→  const storageService = createStorageServiceFromConfig(config);
500→  const app = await createApp(db as any, {
501→    uiMode,
502→    serverPort: listenPort,
503→    storageService,
504→    deploymentMode: config.deploymentMode,
505→    deploymentExposure: config.deploymentExposure,
506→    allowedHostnames: config.allowedHostnames,
507→    bindHost: config.host,
508→    authReady,
509→    companyDeletionEnabled: config.companyDeletionEnabled,
510→    betterAuthHandler,
511→    resolveSession,
512→  });
513→  const server = createServer(app as unknown as Parameters<typeof createServer>[0]);
514→  
515→  if (listenPort !== config.port) {
516→    logger.warn(`Requested port is busy; using next free port (requestedPort=${config.port}, selectedPort=${listenPort})`);
517→  }
518→  
519→  const runtimeListenHost = config.host;
520→  const runtimeApiHost =
521→    runtimeListenHost === "0.0.0.0" || runtimeListenHost === "::"
522→      ? "localhost"
523→      : runtimeListenHost;
524→  process.env.PAPERCLIP_LISTEN_HOST = runtimeListenHost;
525→  process.env.PAPERCLIP_LISTEN_PORT = String(listenPort);
526→  process.env.PAPERCLIP_API_URL = `http://${runtimeApiHost}:${listenPort}`;
527→  
528→  setupLiveEventsWebSocketServer(server, db as any, {
529→    deploymentMode: config.deploymentMode,
530→    resolveSessionFromHeaders,
531→  });
532→
533→  void reconcilePersistedRuntimeServicesOnStartup(db as any)
534→    .then((result) => {
535→      if (result.reconciled > 0) {
536→        logger.warn(
537→          { reconciled: result.reconciled },
538→          "reconciled persisted runtime services from a previous server process",
539→        );
540→      }
541→    })
542→    .catch((err) => {
543→      logger.error({ err }, "startup reconciliation of persisted runtime services failed");
544→    });
545→  
546→  if (config.heartbeatSchedulerEnabled) {
547→    const heartbeat = heartbeatService(db as any);
548→    const routines = routineService(db as any);
549→  
550→    // Reap orphaned running runs at startup while in-memory execution state is empty,
551→    // then resume any persisted queued runs that were waiting on the previous process.
552→    void heartbeat
553→      .reapOrphanedRuns()
554→      .then(() => heartbeat.resumeQueuedRuns())
555→      .catch((err) => {
556→        logger.error({ err }, "startup heartbeat recovery failed");
557→      });
558→    setInterval(() => {
559→      void heartbeat
560→        .tickTimers(new Date())
561→        .then((result) => {
562→          if (result.enqueued > 0) {
563→            logger.info({ ...result }, "heartbeat timer tick enqueued runs");
564→          }
565→        })
566→        .catch((err) => {
567→          logger.error({ err }, "heartbeat timer tick failed");
568→        });
569→
570→      void routines
571→        .tickScheduledTriggers(new Date())
572→        .then((result) => {
573→          if (result.triggered > 0) {
574→            logger.info({ ...result }, "routine scheduler tick enqueued runs");
575→          }
576→        })
577→        .catch((err) => {
578→          logger.error({ err }, "routine scheduler tick failed");
579→        });
580→  
581→      // Periodically reap orphaned runs (5-min staleness threshold) and make sure
582→      // persisted queued work is still being driven forward.
583→      void heartbeat
584→        .reapOrphanedRuns({ staleThresholdMs: 5 * 60 * 1000 })
585→        .then(() => heartbeat.resumeQueuedRuns())
586→        .catch((err) => {
587→          logger.error({ err }, "periodic heartbeat recovery failed");
588→        });
589→    }, config.heartbeatSchedulerIntervalMs);
590→  }
591→  
592→  if (config.databaseBackupEnabled) {
593→    const backupIntervalMs = config.databaseBackupIntervalMinutes * 60 * 1000;
594→    let backupInFlight = false;
595→  
596→    const runScheduledBackup = async () => {
597→      if (backupInFlight) {
598→        logger.warn("Skipping scheduled database backup because a previous backup is still running");
599→        return;
600→      }
601→  
602→      backupInFlight = true;
603→      try {
604→        const result = await runDatabaseBackup({
605→          connectionString: activeDatabaseConnectionString,
606→          backupDir: config.databaseBackupDir,
607→          retentionDays: config.databaseBackupRetentionDays,
608→          filenamePrefix: "paperclip",
609→        });
610→        logger.info(
611→          {
612→            backupFile: result.backupFile,
613→            sizeBytes: result.sizeBytes,
614→            prunedCount: result.prunedCount,
615→            backupDir: config.databaseBackupDir,
616→            retentionDays: config.databaseBackupRetentionDays,
617→          },
618→          `Automatic database backup complete: ${formatDatabaseBackupResult(result)}`,
619→        );
620→      } catch (err) {
621→        logger.error({ err, backupDir: config.databaseBackupDir }, "Automatic database backup failed");
622→      } finally {
623→        backupInFlight = false;
624→      }
625→    };
626→  
627→    logger.info(
628→      {
629→        intervalMinutes: config.databaseBackupIntervalMinutes,
630→        retentionDays: config.databaseBackupRetentionDays,
631→        backupDir: config.databaseBackupDir,
632→      },
633→      "Automatic database backups enabled",
634→    );
635→    setInterval(() => {
636→      void runScheduledBackup();
637→    }, backupIntervalMs);
638→  }
639→  
640→  await new Promise<void>((resolveListen, rejectListen) => {
641→    const onError = (err: Error) => {
642→      server.off("error", onError);
643→      rejectListen(err);
644→    };
645→
646→    server.once("error", onError);
647→    server.listen(listenPort, config.host, () => {
648→      server.off("error", onError);
649→      logger.info(`Server listening on ${config.host}:${listenPort}`);
650→      if (process.env.PAPERCLIP_OPEN_ON_LISTEN === "true") {
651→        const openHost = config.host === "0.0.0.0" || config.host === "::" ? "127.0.0.1" : config.host;
652→        const url = `http://${openHost}:${listenPort}`;
653→        void import("open")
654→          .then((mod) => mod.default(url))
655→          .then(() => {
656→            logger.info(`Opened browser at ${url}`);
657→          })
658→          .catch((err) => {
659→            logger.warn({ err, url }, "Failed to open browser on startup");
660→          });
661→      }
662→      printStartupBanner({
663→        host: config.host,
664→        deploymentMode: config.deploymentMode,
665→        deploymentExposure: config.deploymentExposure,
666→        authReady,
667→        requestedPort: config.port,
668→        listenPort,
669→        uiMode,
670→        db: startupDbInfo,
671→        migrationSummary,
672→        heartbeatSchedulerEnabled: config.heartbeatSchedulerEnabled,
673→        heartbeatSchedulerIntervalMs: config.heartbeatSchedulerIntervalMs,
674→        databaseBackupEnabled: config.databaseBackupEnabled,
675→        databaseBackupIntervalMinutes: config.databaseBackupIntervalMinutes,
676→        databaseBackupRetentionDays: config.databaseBackupRetentionDays,
677→        databaseBackupDir: config.databaseBackupDir,
678→      });
679→
680→      const boardClaimUrl = getBoardClaimWarningUrl(config.host, listenPort);
681→      if (boardClaimUrl) {
682→        const red = "\x1b[41m\x1b[30m";
683→        const yellow = "\x1b[33m";
684→        const reset = "\x1b[0m";
685→        console.log(
686→          [
687→            `${red}  BOARD CLAIM REQUIRED  ${reset}`,
688→            `${yellow}This instance was previously local_trusted and still has local-board as the only admin.${reset}`,
689→            `${yellow}Sign in with a real user and open this one-time URL to claim ownership:${reset}`,
690→            `${yellow}${boardClaimUrl}${reset}`,
691→            `${yellow}If you are connecting over Tailscale, replace the host in this URL with your Tailscale IP/MagicDNS name.${reset}`,
692→          ].join("\n"),
693→        );
694→      }
695→
696→      resolveListen();
697→    });
698→  });
699→  
700→  if (embeddedPostgres && embeddedPostgresStartedByThisProcess) {
701→    const shutdown = async (signal: "SIGINT" | "SIGTERM") => {
702→      logger.info({ signal }, "Stopping embedded PostgreSQL");
703→      try {
704→        await embeddedPostgres?.stop();
705→      } catch (err) {
706→        logger.error({ err }, "Failed to stop embedded PostgreSQL cleanly");
707→      } finally {
708→        process.exit(0);
709→      }
710→    };
711→  
712→    process.once("SIGINT", () => {
713→      void shutdown("SIGINT");
714→    });
715→    process.once("SIGTERM", () => {
716→      void shutdown("SIGTERM");
717→    });
718→  }
719→
720→  return {
721→    server,
722→    host: config.host,
723→    listenPort,
724→    apiUrl: process.env.PAPERCLIP_API_URL ?? `http://${runtimeApiHost}:${listenPort}`,
725→    databaseUrl: activeDatabaseConnectionString,
726→  };
727→}
