729→function isMainModule(metaUrl: string): boolean {
730→  const entry = process.argv[1];
731→  if (!entry) return false;
732→  try {
733→    return pathToFileURL(resolve(entry)).href === metaUrl;
734→  } catch {
735→    return false;
736→  }
737→}
738→
739→if (isMainModule(import.meta.url)) {
740→  void startServer().catch((err) => {
741→    logger.error({ err }, "Paperclip server failed to start");
742→    process.exit(1);
743→  });
744→}
