 75→export function loadConfig(): Config {
 76→  const fileConfig = readConfigFile();
 77→  const fileDatabaseMode =
 78→    (fileConfig?.database.mode === "postgres" ? "postgres" : "embedded-postgres") as DatabaseMode;
 79→
 80→  const fileDbUrl =
 81→    fileDatabaseMode === "postgres"
 82→      ? fileConfig?.database.connectionString
 83→      : undefined;
 84→  const fileDatabaseBackup = fileConfig?.database.backup;
 85→  const fileSecrets = fileConfig?.secrets;
 86→  const fileStorage = fileConfig?.storage;
 87→  const strictModeFromEnv = process.env.PAPERCLIP_SECRETS_STRICT_MODE;
 88→  const secretsStrictMode =
 89→    strictModeFromEnv !== undefined
 90→      ? strictModeFromEnv === "true"
 91→      : (fileSecrets?.strictMode ?? false);
 92→
 93→  const providerFromEnvRaw = process.env.PAPERCLIP_SECRETS_PROVIDER;
 94→  const providerFromEnv =
 95→    providerFromEnvRaw && SECRET_PROVIDERS.includes(providerFromEnvRaw as SecretProvider)
 96→      ? (providerFromEnvRaw as SecretProvider)
 97→      : null;
 98→  const providerFromFile = fileSecrets?.provider;
 99→  const secretsProvider: SecretProvider = providerFromEnv ?? providerFromFile ?? "local_encrypted";
100→
101→  const storageProviderFromEnvRaw = process.env.PAPERCLIP_STORAGE_PROVIDER;
102→  const storageProviderFromEnv =
103→    storageProviderFromEnvRaw && STORAGE_PROVIDERS.includes(storageProviderFromEnvRaw as StorageProvider)
104→      ? (storageProviderFromEnvRaw as StorageProvider)
105→      : null;
106→  const storageProvider: StorageProvider = storageProviderFromEnv ?? fileStorage?.provider ?? "local_disk";
107→  const storageLocalDiskBaseDir = resolveHomeAwarePath(
108→    process.env.PAPERCLIP_STORAGE_LOCAL_DIR ??
109→      fileStorage?.localDisk?.baseDir ??
110→      resolveDefaultStorageDir(),
111→  );
112→  const storageS3Bucket = process.env.PAPERCLIP_STORAGE_S3_BUCKET ?? fileStorage?.s3?.bucket ?? "paperclip";
113→  const storageS3Region = process.env.PAPERCLIP_STORAGE_S3_REGION ?? fileStorage?.s3?.region ?? "us-east-1";
114→  const storageS3Endpoint = process.env.PAPERCLIP_STORAGE_S3_ENDPOINT ?? fileStorage?.s3?.endpoint ?? undefined;
115→  const storageS3Prefix = process.env.PAPERCLIP_STORAGE_S3_PREFIX ?? fileStorage?.s3?.prefix ?? "";
116→  const storageS3ForcePathStyle =
117→    process.env.PAPERCLIP_STORAGE_S3_FORCE_PATH_STYLE !== undefined
118→      ? process.env.PAPERCLIP_STORAGE_S3_FORCE_PATH_STYLE === "true"
119→      : (fileStorage?.s3?.forcePathStyle ?? false);
120→
121→  const deploymentModeFromEnvRaw = process.env.PAPERCLIP_DEPLOYMENT_MODE;
122→  const deploymentModeFromEnv =
123→    deploymentModeFromEnvRaw && DEPLOYMENT_MODES.includes(deploymentModeFromEnvRaw as DeploymentMode)
124→      ? (deploymentModeFromEnvRaw as DeploymentMode)
125→      : null;
126→  const deploymentMode: DeploymentMode = deploymentModeFromEnv ?? fileConfig?.server.deploymentMode ?? "local_trusted";
127→  const deploymentExposureFromEnvRaw = process.env.PAPERCLIP_DEPLOYMENT_EXPOSURE;
128→  const deploymentExposureFromEnv =
129→    deploymentExposureFromEnvRaw &&
130→    DEPLOYMENT_EXPOSURES.includes(deploymentExposureFromEnvRaw as DeploymentExposure)
131→      ? (deploymentExposureFromEnvRaw as DeploymentExposure)
132→      : null;
133→  const deploymentExposure: DeploymentExposure =
134→    deploymentMode === "local_trusted"
135→      ? "private"
136→      : (deploymentExposureFromEnv ?? fileConfig?.server.exposure ?? "private");
137→  const authBaseUrlModeFromEnvRaw = process.env.PAPERCLIP_AUTH_BASE_URL_MODE;
138→  const authBaseUrlModeFromEnv =
139→    authBaseUrlModeFromEnvRaw &&
140→    AUTH_BASE_URL_MODES.includes(authBaseUrlModeFromEnvRaw as AuthBaseUrlMode)
141→      ? (authBaseUrlModeFromEnvRaw as AuthBaseUrlMode)
142→      : null;
143→  const publicUrlFromEnv = process.env.PAPERCLIP_PUBLIC_URL;
144→  const authPublicBaseUrlRaw =
145→    process.env.PAPERCLIP_AUTH_PUBLIC_BASE_URL ??
146→    process.env.BETTER_AUTH_URL ??
147→    process.env.BETTER_AUTH_BASE_URL ??
148→    publicUrlFromEnv ??
149→    fileConfig?.auth?.publicBaseUrl;
150→  const authPublicBaseUrl = authPublicBaseUrlRaw?.trim() || undefined;
151→  const authBaseUrlMode: AuthBaseUrlMode =
152→    authBaseUrlModeFromEnv ??
153→    fileConfig?.auth?.baseUrlMode ??
154→    (authPublicBaseUrl ? "explicit" : "auto");
155→  const disableSignUpFromEnv = process.env.PAPERCLIP_AUTH_DISABLE_SIGN_UP;
156→  const authDisableSignUp: boolean =
157→    disableSignUpFromEnv !== undefined
158→      ? disableSignUpFromEnv === "true"
159→      : (fileConfig?.auth?.disableSignUp ?? false);
160→  const allowedHostnamesFromEnvRaw = process.env.PAPERCLIP_ALLOWED_HOSTNAMES;
161→  const allowedHostnamesFromEnv = allowedHostnamesFromEnvRaw
162→    ? allowedHostnamesFromEnvRaw
163→      .split(",")
164→      .map((value) => value.trim().toLowerCase())
165→      .filter((value) => value.length > 0)
166→    : null;
167→  const publicUrlHostname = authPublicBaseUrl
168→    ? (() => {
169→      try {
170→        return new URL(authPublicBaseUrl).hostname.trim().toLowerCase();
171→      } catch {
172→        return null;
173→      }
174→    })()
175→    : null;
176→  const allowedHostnames = Array.from(
177→    new Set(
178→      [
179→        ...(allowedHostnamesFromEnv ?? fileConfig?.server.allowedHostnames ?? []),
180→        ...(publicUrlHostname ? [publicUrlHostname] : []),
181→      ]
182→        .map((value) => value.trim().toLowerCase())
183→        .filter(Boolean),
184→    ),
185→  );
186→  const companyDeletionEnvRaw = process.env.PAPERCLIP_ENABLE_COMPANY_DELETION;
187→  const companyDeletionEnabled =
188→    companyDeletionEnvRaw !== undefined
189→      ? companyDeletionEnvRaw === "true"
190→      : deploymentMode === "local_trusted";
191→  const databaseBackupEnabled =
192→    process.env.PAPERCLIP_DB_BACKUP_ENABLED !== undefined
193→      ? process.env.PAPERCLIP_DB_BACKUP_ENABLED === "true"
194→      : (fileDatabaseBackup?.enabled ?? true);
195→  const databaseBackupIntervalMinutes = Math.max(
196→    1,
197→    Number(process.env.PAPERCLIP_DB_BACKUP_INTERVAL_MINUTES) ||
198→      fileDatabaseBackup?.intervalMinutes ||
199→      60,
200→  );
201→  const databaseBackupRetentionDays = Math.max(
202→    1,
203→    Number(process.env.PAPERCLIP_DB_BACKUP_RETENTION_DAYS) ||
204→      fileDatabaseBackup?.retentionDays ||
205→      30,
206→  );
207→  const databaseBackupDir = resolveHomeAwarePath(
208→    process.env.PAPERCLIP_DB_BACKUP_DIR ??
209→      fileDatabaseBackup?.dir ??
210→      resolveDefaultBackupDir(),
211→  );
212→
213→  return {
214→    deploymentMode,
215→    deploymentExposure,
216→    host: process.env.HOST ?? fileConfig?.server.host ?? "127.0.0.1",
217→    port: Number(process.env.PORT) || fileConfig?.server.port || 3100,
218→    allowedHostnames,
219→    authBaseUrlMode,
220→    authPublicBaseUrl,
221→    authDisableSignUp,
222→    databaseMode: fileDatabaseMode,
223→    databaseUrl: process.env.DATABASE_URL ?? fileDbUrl,
224→    embeddedPostgresDataDir: resolveHomeAwarePath(
225→      fileConfig?.database.embeddedPostgresDataDir ?? resolveDefaultEmbeddedPostgresDir(),
226→    ),
227→    embeddedPostgresPort: fileConfig?.database.embeddedPostgresPort ?? 54329,
228→    databaseBackupEnabled,
229→    databaseBackupIntervalMinutes,
230→    databaseBackupRetentionDays,
231→    databaseBackupDir,
232→    serveUi:
233→      process.env.SERVE_UI !== undefined
234→        ? process.env.SERVE_UI === "true"
235→        : fileConfig?.server.serveUi ?? true,
236→    uiDevMiddleware: process.env.PAPERCLIP_UI_DEV_MIDDLEWARE === "true",
237→    secretsProvider,
238→    secretsStrictMode,
239→    secretsMasterKeyFilePath:
240→      resolveHomeAwarePath(
241→        process.env.PAPERCLIP_SECRETS_MASTER_KEY_FILE ??
242→          fileSecrets?.localEncrypted.keyFilePath ??
243→          resolveDefaultSecretsKeyFilePath(),
244→      ),
245→    storageProvider,
246→    storageLocalDiskBaseDir,
247→    storageS3Bucket,
248→    storageS3Region,
249→    storageS3Endpoint,
250→    storageS3Prefix,
251→    storageS3ForcePathStyle,
252→    heartbeatSchedulerEnabled: process.env.HEARTBEAT_SCHEDULER_ENABLED !== "false",
253→    heartbeatSchedulerIntervalMs: Math.max(10000, Number(process.env.HEARTBEAT_SCHEDULER_INTERVAL_MS) || 30000),
254→    companyDeletionEnabled,
255→  };
256→}
