 98→export const paperclipConfigSchema = z
 99→  .object({
100→    $meta: configMetaSchema,
101→    llm: llmConfigSchema.optional(),
102→    database: databaseConfigSchema,
103→    logging: loggingConfigSchema,
104→    server: serverConfigSchema,
105→    auth: authConfigSchema.default({
106→      baseUrlMode: "auto",
107→      disableSignUp: false,
108→    }),
109→    storage: storageConfigSchema.default({
110→      provider: "local_disk",
111→      localDisk: {
112→        baseDir: "~/.paperclip/instances/default/data/storage",
113→      },
114→      s3: {
115→        bucket: "paperclip",
116→        region: "us-east-1",
117→        prefix: "",
118→        forcePathStyle: false,
119→      },
120→    }),
121→    secrets: secretsConfigSchema.default({
122→      provider: "local_encrypted",
123→      strictMode: false,
124→      localEncrypted: {
125→        keyFilePath: "~/.paperclip/instances/default/secrets/master.key",
126→      },
127→    }),
128→  })
129→  .superRefine((value, ctx) => {
130→    if (value.server.deploymentMode === "local_trusted") {
131→      if (value.server.exposure !== "private") {
132→        ctx.addIssue({
133→          code: z.ZodIssueCode.custom,
134→          message: "server.exposure must be private when deploymentMode is local_trusted",
135→          path: ["server", "exposure"],
136→        });
137→      }
138→      return;
139→    }
140→
141→    if (value.auth.baseUrlMode === "explicit" && !value.auth.publicBaseUrl) {
142→      ctx.addIssue({
143→        code: z.ZodIssueCode.custom,
144→        message: "auth.publicBaseUrl is required when auth.baseUrlMode is explicit",
145→        path: ["auth", "publicBaseUrl"],
146→      });
147→    }
148→
149→    if (value.server.exposure === "public" && value.auth.baseUrlMode !== "explicit") {
150→      ctx.addIssue({
151→        code: z.ZodIssueCode.custom,
152→        message: "auth.baseUrlMode must be explicit when deploymentMode=authenticated and exposure=public",
153→        path: ["auth", "baseUrlMode"],
154→      });
155→    }
156→
157→    if (value.server.exposure === "public" && !value.auth.publicBaseUrl) {
158→      ctx.addIssue({
159→        code: z.ZodIssueCode.custom,
160→        message: "auth.publicBaseUrl is required when deploymentMode=authenticated and exposure=public",
161→        path: ["auth", "publicBaseUrl"],
162→      });
163→    }
164→  });
