 21→async function materializeInstructions(role: string): Promise<string | null> {
 22→  const projectRoot = resolveProjectRoot();
 23→  if (!projectRoot) return null;
 24→
 25→  let instructionsDir: string;
 26→  try {
 27→    instructionsDir = resolveAgentInstructionsDir(role);
 28→  } catch {
 29→    return null;
 30→  }
 31→
 32→  // Idempotent: skip if already exists
 33→  try {
 34→    await fs.access(instructionsDir);
 35→    return instructionsDir;
 36→  } catch {
 37→    // Directory doesn't exist, create it
 38→  }
 39→
 40→  const bundleRole = role === "ceo" ? "ceo" : "default";
 41→  const bundle = await loadDefaultAgentInstructionsBundle(bundleRole as "ceo" | "default");
 42→
 43→  await fs.mkdir(instructionsDir, { recursive: true });
 44→  for (const [fileName, content] of Object.entries(bundle)) {
 45→    await fs.writeFile(path.join(instructionsDir, fileName), content, "utf8");
 46→  }
 47→
 48→  logger.info(
 49→    { role, instructionsDir, files: Object.keys(bundle) },
 50→    "Materialized default agent instructions to project",
 51→  );
 52→
 53→  return instructionsDir;
 54→}
