 56→export function bootstrapService(db: Db) {
 57→  const isEnabled = process.env.PAPERCLIP_AUTO_BOOTSTRAP !== "false";
 58→
 59→  async function maybeBootstrapUser(
 60→    userId: string,
 61→    userName?: string | null,
 62→  ): Promise<BootstrapResult> {
 63→    if (!isEnabled) return { action: "noop" };
 64→
 65→    // Check if user already has any company memberships
 66→    const existingMemberships = await db
 67→      .select({ id: companyMemberships.id })
 68→      .from(companyMemberships)
 69→      .where(
 70→        and(
 71→          eq(companyMemberships.principalType, "user"),
 72→          eq(companyMemberships.principalId, userId),
 73→          eq(companyMemberships.status, "active"),
 74→        ),
 75→      )
 76→      .limit(1);
 77→
 78→    if (existingMemberships.length > 0) {
 79→      return { action: "noop" };
 80→    }
 81→
 82→    // Check if any companies exist
 83→    const [companyCount] = await db
 84→      .select({ count: count() })
 85→      .from(companies);
 86→
 87→    if (companyCount.count === 0) {
 88→      // First user: create default company + agent, promote to admin
 89→      return createDefaultSetup(userId, userName);
 90→    }
 91→
 92→    // Companies exist but user has no membership: assign to first company
 93→    const [firstCompany] = await db
 94→      .select({ id: companies.id })
 95→      .from(companies)
 96→      .limit(1);
 97→
 98→    if (firstCompany) {
 99→      await db.insert(companyMemberships).values({
100→        companyId: firstCompany.id,
101→        principalType: "user",
102→        principalId: userId,
103→        status: "active",
104→        membershipRole: "member",
105→      });
106→
107→      logger.info(
108→        { userId, companyId: firstCompany.id },
109→        "Auto-assigned user to existing company",
110→      );
111→
112→      return { action: "assigned_to_company", companyId: firstCompany.id };
113→    }
114→
115→    return { action: "noop" };
116→  }
