118→  async function createDefaultSetup(
119→    userId: string,
120→    userName?: string | null,
121→  ): Promise<BootstrapResult> {
122→    const companyName =
123→      process.env.PAPERCLIP_DEFAULT_COMPANY_NAME || "My Company";
124→    const agentName =
125→      process.env.PAPERCLIP_DEFAULT_AGENT_NAME || "CEO Agent";
126→
127→    // Create company
128→    const [company] = await db
129→      .insert(companies)
130→      .values({ name: companyName })
131→      .returning();
132→
133→    // Promote user to instance_admin
134→    const existingRole = await db
135→      .select({ id: instanceUserRoles.id })
136→      .from(instanceUserRoles)
137→      .where(
138→        and(
139→          eq(instanceUserRoles.userId, userId),
140→          eq(instanceUserRoles.role, "instance_admin"),
141→        ),
142→      )
143→      .then((rows) => rows[0] ?? null);
144→
145→    if (!existingRole) {
146→      await db.insert(instanceUserRoles).values({
147→        userId,
148→        role: "instance_admin",
149→      });
150→    }
151→
152→    // Set role on authUsers table
153→    await db
154→      .update(authUsers)
155→      .set({ role: "superadmin" })
156→      .where(eq(authUsers.id, userId));
157→
158→    // Assign user as owner
159→    await db.insert(companyMemberships).values({
160→      companyId: company.id,
161→      principalType: "user",
162→      principalId: userId,
163→      status: "active",
164→      membershipRole: "owner",
165→    });
166→
167→    // Materialize CEO instructions to project-local agents/ceo/
168→    const instructionsDir = await materializeInstructions("ceo");
169→    const projectRoot = resolveProjectRoot();
170→    const ceoCommand = process.env.PAPERCLIP_CEO_COMMAND || "claude";
171→
172→    // Build adapterConfig for claude-local
173→    const adapterConfig: Record<string, unknown> = {};
174→    adapterConfig.command = ceoCommand;
175→    if (projectRoot) {
176→      adapterConfig.cwd = projectRoot;
177→    }
178→    if (instructionsDir) {
179→      adapterConfig.instructionsBundleMode = "external";
180→      adapterConfig.instructionsRootPath = instructionsDir;
181→      adapterConfig.instructionsEntryFile = "AGENTS.md";
182→    }
183→
184→    // Create default CEO agent
185→    await db.insert(agents).values({
186→      companyId: company.id,
187→      name: agentName,
188→      role: "ceo",
189→      title: "Chief Executive Officer",
190→      adapterType: "claude-local",
191→      adapterConfig,
192→    });
193→
194→    logger.info(
195→      { userId, companyId: company.id, companyName, agentName },
196→      "Auto-bootstrap: created default company and agent for first user",
197→    );
198→
199→    return { action: "created_company", companyId: company.id };
200→  }
201→
202→  return { maybeBootstrapUser };
203→}
