 1→export type AuthSession = {
 2→  session: { id: string; userId: string };
 3→  user: { id: string; email: string | null; name: string | null };
 4→};
 5→
 6→function toSession(value: unknown): AuthSession | null {
 7→  if (!value || typeof value !== "object") return null;
 8→  const record = value as Record<string, unknown>;
 9→  const sessionValue = record.session;
10→  const userValue = record.user;
11→  if (!sessionValue || typeof sessionValue !== "object") return null;
12→  if (!userValue || typeof userValue !== "object") return null;
13→  const session = sessionValue as Record<string, unknown>;
14→  const user = userValue as Record<string, unknown>;
15→  if (typeof session.id !== "string" || typeof session.userId !== "string") return null;
16→  if (typeof user.id !== "string") return null;
17→  return {
18→    session: { id: session.id, userId: session.userId },
19→    user: {
20→      id: user.id,
21→      email: typeof user.email === "string" ? user.email : null,
22→      name: typeof user.name === "string" ? user.name : null,
23→    },
24→  };
25→}
26→
27→async function authPost(path: string, body: Record<string, unknown>) {
28→  const res = await fetch(`/api/auth${path}`, {
29→    method: "POST",
30→    credentials: "include",
31→    headers: { "Content-Type": "application/json" },
32→    body: JSON.stringify(body),
33→  });
34→  const payload = await res.json().catch(() => null);
35→  if (!res.ok) {
36→    const message =
37→      (payload as { error?: { message?: string } | string } | null)?.error &&
38→      typeof (payload as { error?: { message?: string } | string }).error === "object"
39→        ? ((payload as { error?: { message?: string } }).error?.message ?? `Request failed: ${res.status}`)
40→        : (payload as { error?: string } | null)?.error ?? `Request failed: ${res.status}`;
41→    throw new Error(message);
42→  }
43→  return payload;
44→}
45→
46→export const authApi = {
47→  getSession: async (): Promise<AuthSession | null> => {
48→    const res = await fetch("/api/auth/get-session", {
49→      credentials: "include",
50→      headers: { Accept: "application/json" },
51→    });
52→    if (res.status === 401) return null;
53→    const payload = await res.json().catch(() => null);
54→    if (!res.ok) {
55→      throw new Error(`Failed to load session (${res.status})`);
56→    }
57→    const direct = toSession(payload);
58→    if (direct) return direct;
59→    const nested = payload && typeof payload === "object" ? toSession((payload as Record<string, unknown>).data) : null;
60→    return nested;
61→  },
62→
63→  signInEmail: async (input: { email: string; password: string }) => {
64→    await authPost("/sign-in/email", input);
65→  },
66→
67→  signUpEmail: async (input: { name: string; email: string; password: string }) => {
68→    await authPost("/sign-up/email", input);
69→  },
70→
71→  signOut: async () => {
72→    await authPost("/sign-out", {});
73→  },
74→};
