 1→import { Router } from "express";
 2→import type { Db } from "@paperclipai/db";
 3→import { and, count, eq, gt, inArray, isNull, sql } from "drizzle-orm";
 4→import { heartbeatRuns, instanceUserRoles, invites } from "@paperclipai/db";
 5→import type { DeploymentExposure, DeploymentMode } from "@paperclipai/shared";
 6→import { readPersistedDevServerStatus, toDevServerHealthStatus } from "../dev-server-status.js";
 7→import { instanceSettingsService } from "../services/instance-settings.js";
 8→import { serverVersion } from "../version.js";
 9→
10→export function healthRoutes(
11→  db?: Db,
12→  opts: {
13→    deploymentMode: DeploymentMode;
14→    deploymentExposure: DeploymentExposure;
15→    authReady: boolean;
16→    companyDeletionEnabled: boolean;
17→  } = {
18→    deploymentMode: "local_trusted",
19→    deploymentExposure: "private",
20→    authReady: true,
21→    companyDeletionEnabled: true,
22→  },
23→) {
24→  const router = Router();
25→
26→  router.get("/", async (_req, res) => {
27→    if (!db) {
28→      res.json({ status: "ok", version: serverVersion });
29→      return;
30→    }
31→
32→    let bootstrapStatus: "ready" | "bootstrap_pending" = "ready";
33→    let bootstrapInviteActive = false;
34→    if (opts.deploymentMode === "authenticated") {
35→      const roleCount = await db
36→        .select({ count: count() })
37→        .from(instanceUserRoles)
38→        .where(sql`${instanceUserRoles.role} = 'instance_admin'`)
39→        .then((rows) => Number(rows[0]?.count ?? 0));
40→      const autoBootstrapEnabled = process.env.PAPERCLIP_AUTO_BOOTSTRAP !== "false";
41→      bootstrapStatus = roleCount > 0 || autoBootstrapEnabled ? "ready" : "bootstrap_pending";
42→
43→      if (bootstrapStatus === "bootstrap_pending") {
44→        const now = new Date();
45→        const inviteCount = await db
46→          .select({ count: count() })
47→          .from(invites)
48→          .where(
49→            and(
50→              eq(invites.inviteType, "bootstrap_ceo"),
51→              isNull(invites.revokedAt),
52→              isNull(invites.acceptedAt),
53→              gt(invites.expiresAt, now),
54→            ),
55→          )
56→          .then((rows) => Number(rows[0]?.count ?? 0));
57→        bootstrapInviteActive = inviteCount > 0;
58→      }
59→    }
60→
61→    const persistedDevServerStatus = readPersistedDevServerStatus();
62→    let devServer: ReturnType<typeof toDevServerHealthStatus> | undefined;
63→    if (persistedDevServerStatus) {
64→      const instanceSettings = instanceSettingsService(db);
65→      const experimentalSettings = await instanceSettings.getExperimental();
66→      const activeRunCount = await db
67→        .select({ count: count() })
68→        .from(heartbeatRuns)
69→        .where(inArray(heartbeatRuns.status, ["queued", "running"]))
70→        .then((rows) => Number(rows[0]?.count ?? 0));
71→
72→      devServer = toDevServerHealthStatus(persistedDevServerStatus, {
73→        autoRestartEnabled: experimentalSettings.autoRestartDevServerWhenIdle ?? false,
74→        activeRunCount,
75→      });
76→    }
77→
78→    res.json({
79→      status: "ok",
80→      version: serverVersion,
81→      deploymentMode: opts.deploymentMode,
82→      deploymentExposure: opts.deploymentExposure,
83→      authReady: opts.authReady,
84→      bootstrapStatus,
85→      bootstrapInviteActive,
86→      features: {
87→        companyDeletionEnabled: opts.companyDeletionEnabled,
88→      },
89→      ...(devServer ? { devServer } : {}),
90→    });
91→  });
92→
93→  return router;
94→}
