              className={`inline-flex rounded-full px-2 py-0.5 text-xs font-medium ${ROLE_COLORS[user.role] ?? ""}`}
            >
              {ROLE_LABELS[user.role] ?? user.role}
            </span>
            <div className="flex items-center gap-1">
              {canAssignRole && user.id !== currentUser?.id && canActorChangeTarget(currentUser?.role, user.role) && (
                <button
                  onClick={() => setRoleUser(user)}
                  className="rounded p-1 hover:bg-muted"
                  title="Change role"
                >
                  <Shield className="h-4 w-4" />
                </button>
              )}
              {canDelete && user.id !== currentUser?.id && user.role !== "superadmin" && (
                <button
                  onClick={() => {
                    if (confirm(`Delete user "${user.name}"?`)) {
                      deleteMutation.mutate(user.id);
                    }
                  }}
                  className="rounded p-1 hover:bg-muted text-destructive"
                  title="Delete user"
                >
                  <Trash2 className="h-4 w-4" />
                </button>
              )}
            </div>
          </div>
        ))}
        {usersQuery.data?.length === 0 && (
          <div className="px-4 py-8 text-center text-sm text-muted-foreground">
            No users found
          </div>
        )}
      </div>

      {/* Create User Dialog */}
      <Dialog open={createOpen} onOpenChange={setCreateOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Create User</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <label className="text-xs text-muted-foreground">Name</label>
              <input
                className="mt-1 w-full rounded-md border border-border bg-transparent px-2.5 py-1.5 text-sm"
                value={newName}
                onChange={(e) => setNewName(e.target.value)}
              />
            </div>
            <div>
              <label className="text-xs text-muted-foreground">Email</label>
              <input
                className="mt-1 w-full rounded-md border border-border bg-transparent px-2.5 py-1.5 text-sm"
                type="email"
                value={newEmail}
                onChange={(e) => setNewEmail(e.target.value)}
              />
            </div>
            <div>
              <label className="text-xs text-muted-foreground">Password</label>
              <input
                className="mt-1 w-full rounded-md border border-border bg-transparent px-2.5 py-1.5 text-sm"
                type="password"
                value={newPassword}
                onChange={(e) => setNewPassword(e.target.value)}
              />
            </div>
            <div>
              <label className="text-xs text-muted-foreground">Role</label>
              <select
                className="mt-1 w-full rounded-md border border-border bg-transparent px-2.5 py-1.5 text-sm"
                value={newRole}
                onChange={(e) => setNewRole(e.target.value)}
              >
                {allowedRoles.map((r) => (
                  <option key={r} value={r}>
                    {ROLE_LABELS[r]}
                  </option>
                ))}
              </select>
            </div>
          </div>
          <DialogFooter>
            <Button
              onClick={() =>
                createMutation.mutate({
                  name: newName,
                  email: newEmail,
                  password: newPassword,
                  role: newRole,
                  companyIds: selectedCompany ? [selectedCompany.id] : [],
                })
              }
              disabled={createMutation.isPending || !newName || !newEmail || !newPassword}
            >
              {createMutation.isPending ? "Creating..." : "Create"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Change Role Dialog */}
      <ChangeRoleDialog
        user={roleUser}
        allowedRoles={allowedRoles}
        isPending={roleMutation.isPending}
        onSave={(id, role) => roleMutation.mutate({ id, role })}
        onClose={() => setRoleUser(null)}
      />
    </div>
  );
}

function ChangeRoleDialog({
  user,
  allowedRoles,
  isPending,
  onSave,
  onClose,
}: {
  user: User | null;
  allowedRoles: string[];
  isPending: boolean;
  onSave: (id: string, role: string) => void;
  onClose: () => void;
}) {
  const [selectedRole, setSelectedRole] = useState(user?.role ?? "guest");

  useEffect(() => {
    if (user) setSelectedRole(user.role);
  }, [user]);

  return (
    <Dialog open={!!user} onOpenChange={() => onClose()}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Change Role — {user?.name}</DialogTitle>
        </DialogHeader>
        <div className="space-y-3">
          {allowedRoles.map((r) => (
            <label key={r} className="flex items-center gap-2 cursor-pointer">
              <input
                type="radio"
                name="role"
                value={r}
                checked={selectedRole === r}
                onChange={() => setSelectedRole(r)}
                className="accent-primary"
              />
              <span className="text-sm">{ROLE_LABELS[r]}</span>
            </label>
          ))}
        </div>
        <DialogFooter>
          <Button
            onClick={() => {
              if (user) onSave(user.id, selectedRole);
            }}
            disabled={isPending}
          >
            {isPending ? "Saving..." : "Save"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
